window.FITKAL_RECIPES=[{"id":"kah-01","category":"kahvalti","title":"Klasik Menemen","fit":false,"desc":"Domates, biber ve yumurtanın tavada buluştuğu, ekmek bandırmalık sulu bir kahvaltı klasiği.","time":20,"servings":2,"difficulty":"Kolay","kcal":250,"protein":14,"carbs":12,"fat":16,"tags":["geleneksel","yumurtalı","vejetaryen"],"ingredients":["3 adet yumurta","3 adet olgun domates","2 adet sivri biber","1 adet küçük soğan (isteğe bağlı)","1 yemek kaşığı zeytinyağı","1 tatlı kaşığı tereyağı","1/2 çay kaşığı tuz","1 tutam pul biber"],"steps":["Biberleri ince doğrayın, domatesleri kabuklarını soyup küp küp kesin.","Tavada zeytinyağı ve tereyağını ısıtın, biberleri (varsa soğanla) 4-5 dakika kavurun.","Domatesleri ekleyip suyunu biraz çekene kadar orta ateşte pişirin.","Yumurtaları kırın, hafifçe karıştırarak kıvam alana dek pişirin.","Tuz ve pul biberle tatlandırıp sıcak servis edin."]},{"id":"kah-02","category":"kahvalti","title":"Yoğurtlu Çılbır","fit":false,"desc":"Sarımsaklı yoğurt üzerine poşe yumurta ve kızgın pul biberli tereyağıyla zengin bir kahvaltı.","time":20,"servings":2,"difficulty":"Orta","kcal":275,"protein":16,"carbs":8,"fat":20,"tags":["geleneksel","yumurtalı","yoğurtlu"],"ingredients":["4 adet yumurta","250 g süzme yoğurt","1 diş sarımsak","25 g tereyağı","1 tatlı kaşığı pul biber","1 yemek kaşığı sirke","1 litre su","1 tutam tuz"],"steps":["Yoğurdu rendelenmiş sarımsak ve tuzla çırpıp oda sıcaklığında iki tabağa paylaştırın.","Suyu sirkeyle birlikte hafif kaynama noktasına getirin.","Yumurtaları tek tek bir kaseye kırıp suya bırakın ve 3 dakika pişirin.","Delikli kepçeyle alıp yoğurdun üzerine yerleştirin.","Tereyağını eritip pul biberi ekleyin, köpürünce yumurtaların üzerine gezdirin."]},{"id":"kah-03","category":"kahvalti","title":"Sucuklu Yumurta","fit":false,"desc":"Sahanda kızaran sucuk dilimleri ve akışkan sarılı yumurtalarla doyurucu bir hafta sonu kahvaltısı.","time":15,"servings":2,"difficulty":"Kolay","kcal":360,"protein":20,"carbs":2,"fat":30,"tags":["geleneksel","yumurtalı","hızlı"],"ingredients":["4 adet yumurta","80 g sucuk","1 tatlı kaşığı tereyağı","1 tutam tuz","1 tutam karabiber","Servis için maydanoz"],"steps":["Sucuğun zarını soyup ince halkalar halinde dilimleyin.","Sahanda tereyağını eritip sucukları iki yüzü hafif kızarana dek çevirin.","Yumurtaları sucukların arasına kırın, kapağını kapatıp kısık ateşte 3-4 dakika pişirin.","Tuz ve karabiber serpip kıyılmış maydanozla servis edin."]},{"id":"kah-04","category":"kahvalti","title":"Ev Yapımı Pankek","fit":false,"desc":"Yumuşacık dokulu, bal veya meyveyle servis edilen kabarık pankekler.","time":25,"servings":3,"difficulty":"Kolay","kcal":330,"protein":10,"carbs":48,"fat":11,"tags":["tatlı kahvaltı","çocuklar sever","vejetaryen"],"ingredients":["200 g un","250 ml süt","1 adet yumurta","25 g eritilmiş tereyağı","1 yemek kaşığı toz şeker","1 tatlı kaşığı kabartma tozu","1 tutam tuz","Servis için 2 yemek kaşığı bal"],"steps":["Un, şeker, kabartma tozu ve tuzu bir kapta karıştırın.","Başka kapta süt, yumurta ve eritilmiş tereyağını çırpın.","Sıvı karışımı una ekleyip topaksız ama fazla çırpmadan birleştirin.","Yapışmaz tavayı hafif yağlayıp her pankek için bir kepçe hamur dökün.","Üzeri kabarcıklanınca çevirin, diğer yüzü de altın rengi olunca alın.","Bal gezdirerek servis edin."]},{"id":"kah-05","category":"kahvalti","title":"Tarçınlı Yumurtalı Ekmek","fit":false,"desc":"Yumurtalı süte batırılıp tavada kızartılan, tarçın kokulu tatlı ekmek dilimleri.","time":15,"servings":2,"difficulty":"Kolay","kcal":340,"protein":14,"carbs":40,"fat":14,"tags":["tatlı kahvaltı","hızlı","vejetaryen"],"ingredients":["4 dilim bayat ekmek","2 adet yumurta","120 ml süt","1 çay kaşığı tarçın","1 tatlı kaşığı toz şeker","1 yemek kaşığı tereyağı","Servis için taze meyve"],"steps":["Yumurta, süt, tarçın ve şekeri geniş bir kapta çırpın.","Ekmek dilimlerini karışıma iki yüzüyle kısa süre batırın.","Tavada tereyağını eritip ekmekleri her iki yüzü altın rengi olana dek kızartın.","Taze meyveyle sıcak servis edin."]},{"id":"kah-06","category":"kahvalti","title":"Hollandez Soslu Poşe Yumurta","fit":false,"desc":"Kızarmış ekmek, füme hindi ve poşe yumurtanın limonlu tereyağı sosuyla buluştuğu şık bir tabak.","time":35,"servings":2,"difficulty":"Zor","kcal":500,"protein":22,"carbs":26,"fat":34,"tags":["brunch","yumurtalı","özel gün"],"ingredients":["4 adet yumurta (poşe için)","2 adet yumurta sarısı (sos için)","2 adet yuvarlak kahvaltılık ekmek","4 dilim füme hindi","60 g tereyağı","1 yemek kaşığı limon suyu","1 yemek kaşığı sirke","1 tutam tuz"],"steps":["Tereyağını eritin; yumurta sarılarını limon suyuyla benmari usulü sürekli çırpın.","Eritilmiş tereyağını ince ince ekleyerek koyu, parlak bir sos elde edin ve tuzlayın.","Ekmekleri ikiye kesip kızartın, üzerlerine hindi dilimlerini koyun.","Sirkeli, hafif kaynayan suda yumurtaları 3 dakika poşe edin.","Yumurtaları ekmeklerin üzerine yerleştirip sosu gezdirerek hemen servis edin."]},{"id":"kah-07","category":"kahvalti","title":"Baharatlı Domates Soslu Yumurta","fit":true,"desc":"Kimyonlu, közlenmiş biber aromalı domates sosunda pişen yumurtalarla tek tavada doyurucu kahvaltı.","time":30,"servings":2,"difficulty":"Kolay","kcal":250,"protein":15,"carbs":18,"fat":13,"tags":["tek tava","yumurtalı","vejetaryen"],"ingredients":["4 adet yumurta","400 g doğranmış domates","1 adet kırmızı kapya biber","1 adet küçük soğan","2 diş sarımsak","1 yemek kaşığı zeytinyağı","1 çay kaşığı kimyon","1 çay kaşığı tatlı toz biber","Servis için taze kişniş veya maydanoz"],"steps":["Soğan ve biberi doğrayıp zeytinyağında yumuşayana dek soteleyin.","Sarımsak, kimyon ve toz biberi ekleyip 1 dakika kavurun.","Domatesi ilave edip sos koyulaşana kadar 10 dakika pişirin.","Sosta dört çukur açıp yumurtaları kırın, kapağı kapatıp 6-7 dakika pişirin.","Yeşilliklerle süsleyip tavada servis edin."]},{"id":"kah-08","category":"kahvalti","title":"Peynirli Ispanaklı Gözleme","fit":false,"desc":"İnce açılmış hamura ıspanak ve beyaz peynir doldurulup sacda veya tavada pişirilen gözleme.","time":45,"servings":3,"difficulty":"Orta","kcal":400,"protein":16,"carbs":50,"fat":15,"tags":["geleneksel","hamur işi","vejetaryen"],"ingredients":["250 g un","140 ml ılık su","1 çay kaşığı tuz","200 g ıspanak","120 g beyaz peynir","1 adet küçük soğan","2 yemek kaşığı zeytinyağı","1 yemek kaşığı tereyağı (fırçalamak için)"],"steps":["Un, su ve tuzu yoğurup yumuşak bir hamur yapın, 20 dakika üzerini örterek bekletin.","Ispanağı ve soğanı ince kıyıp zeytinyağında 3 dakika çevirin, soğuyunca peynirle karıştırın.","Hamuru üç bezeye bölüp oklavayla ince yufka gibi açın.","Yarısına iç harcı yayıp diğer yarısını kapatın, kenarlarını bastırın.","Kızgın tavada iki yüzünü de pişirin, sıcakken tereyağı sürüp dilimleyin."]},{"id":"kah-09","category":"kahvalti","title":"Kaygana","fit":false,"desc":"Yumurta, un ve maydanozla yapılan, krep ile omlet arası nostaljik bir Karadeniz kahvaltılığı.","time":15,"servings":2,"difficulty":"Kolay","kcal":240,"protein":12,"carbs":16,"fat":14,"tags":["geleneksel","yumurtalı","hızlı"],"ingredients":["3 adet yumurta","3 yemek kaşığı un","100 ml süt","1/2 demet maydanoz","3 dal taze soğan","1 yemek kaşığı tereyağı","1/2 çay kaşığı tuz"],"steps":["Yumurta, un, süt ve tuzu pürüzsüz olana dek çırpın.","İnce kıyılmış maydanoz ve taze soğanı karışıma ekleyin.","Tavada tereyağını eritip karışımı ince bir tabaka halinde yayın.","Altı pişince çevirip diğer yüzünü de kızartın, dilimleyerek servis edin."]},{"id":"kah-10","category":"kahvalti","title":"Muzlu Tarçınlı Yulaf Kasesi","fit":true,"desc":"Sütte pişen yulafın muz, ceviz ve tarçınla tamamlandığı, uzun süre tok tutan sıcak bir kase.","time":10,"servings":1,"difficulty":"Kolay","kcal":405,"protein":14,"carbs":62,"fat":11,"tags":["fit","lifli","vejetaryen"],"ingredients":["50 g yulaf ezmesi","200 ml yarım yağlı süt","1 adet küçük muz","10 g ceviz içi","1/2 çay kaşığı tarçın","1 tutam tuz"],"steps":["Yulafı süt ve tuzla küçük bir tencereye alın.","Orta ateşte ara ara karıştırarak 4-5 dakika koyulaşana dek pişirin.","Muzun yarısını ezip yulafa karıştırın, tarçını ekleyin.","Kaseye alıp kalan muz dilimleri ve kırılmış cevizle süsleyin."]},{"id":"kah-11","category":"kahvalti","title":"Gece Bekletmeli Yulaf","fit":true,"desc":"Akşamdan hazırlanıp sabah buzdolabından hazır çıkan, yoğurtlu ve meyveli pratik kavanoz kahvaltısı.","time":10,"servings":1,"difficulty":"Kolay","kcal":360,"protein":18,"carbs":52,"fat":9,"tags":["fit","hazırla-sakla","vejetaryen"],"ingredients":["45 g yulaf ezmesi","120 g yoğurt","100 ml yarım yağlı süt","1 yemek kaşığı chia tohumu","80 g karışık orman meyvesi","1/2 çay kaşığı vanilya özü"],"steps":["Yulaf, chia, yoğurt, süt ve vanilyayı bir kavanozda iyice karıştırın.","Kapağını kapatıp buzdolabında en az 6 saat veya bir gece bekletin.","Sabah karıştırın, kıvam çok koyuysa biraz süt ekleyin.","Meyveleri üzerine koyup soğuk servis edin."]},{"id":"kah-12","category":"kahvalti","title":"Protein Pankek","fit":true,"desc":"Yulaf, yumurta akı ve lor peyniriyle yapılan, şeker eklenmemiş yüksek proteinli pankek.","time":20,"servings":2,"difficulty":"Kolay","kcal":270,"protein":22,"carbs":30,"fat":7,"tags":["fit","yüksek protein","şekersiz"],"ingredients":["60 g yulaf ezmesi","150 g lor peyniri","1 adet yumurta","2 adet yumurta akı","1 adet küçük muz","1 çay kaşığı kabartma tozu","1/2 çay kaşığı tarçın","Birkaç damla zeytinyağı"],"steps":["Yulafı blenderda un kıvamına gelene dek çekin.","Lor, yumurta, yumurta akı, muz, kabartma tozu ve tarçını ekleyip pürüzsüz olana kadar çekin.","Yapışmaz tavayı birkaç damla yağla silip küçük kepçelerle hamur dökün.","Kısık ateşte her iki yüzünü 2'şer dakika pişirin.","Taze meyve veya bir kaşık yoğurtla servis edin."]},{"id":"kah-13","category":"kahvalti","title":"Avokadolu Tam Buğday Tost","fit":true,"desc":"Tam buğday ekmeğine limonlu avokado ezmesi ve haşlanmış yumurta; sağlıklı yağlarla dolu bir başlangıç.","time":15,"servings":1,"difficulty":"Kolay","kcal":330,"protein":14,"carbs":30,"fat":17,"tags":["fit","sağlıklı yağ","vejetaryen"],"ingredients":["2 dilim tam buğday ekmeği","1/2 adet avokado","1 adet yumurta","1 tatlı kaşığı limon suyu","4 adet çeri domates","1 tutam pul biber","1 tutam tuz"],"steps":["Yumurtayı 8 dakika haşlayıp soğuk suya alın ve soyun.","Ekmekleri kızartın.","Avokadoyu limon suyu ve tuzla çatalla ezin.","Ekmeklere avokadoyu sürün, dilimlenmiş yumurta ve domatesleri yerleştirin.","Pul biber serperek servis edin."]},{"id":"kah-14","category":"kahvalti","title":"Sebzeli Fırın Omlet","fit":true,"desc":"Bol sebzeli, az yağla pişen ve lor peyniriyle proteini artırılmış renkli bir omlet.","time":20,"servings":1,"difficulty":"Kolay","kcal":250,"protein":24,"carbs":9,"fat":13,"tags":["fit","düşük karbonhidrat","yumurtalı"],"ingredients":["2 adet yumurta","1 adet yumurta akı","40 g lor peyniri","1 avuç ıspanak","1/2 adet kırmızı biber","4 adet mantar","1 çay kaşığı zeytinyağı","1 tutam tuz ve karabiber"],"steps":["Biber ve mantarı doğrayıp zeytinyağında 4 dakika soteleyin, ıspanağı ekleyip söndürün.","Yumurta ve yumurta akını tuz, karabiberle çırpın.","Yumurtayı sebzelerin üzerine dökün, lor peynirini serpin.","Kapağı kapalı kısık ateşte 5-6 dakika, üzeri tutana dek pişirin.","İkiye katlayıp servis edin."]},{"id":"kah-15","category":"kahvalti","title":"Kakaolu Chia Puding","fit":true,"desc":"Chia tohumlarının sütte şişerek puding kıvamı aldığı, lif ve omega-3 açısından zengin bir kase.","time":10,"servings":1,"difficulty":"Kolay","kcal":285,"protein":12,"carbs":30,"fat":13,"tags":["fit","hazırla-sakla","lifli"],"ingredients":["3 yemek kaşığı chia tohumu","200 ml yarım yağlı süt","1 tatlı kaşığı kakao","1 tatlı kaşığı bal","50 g çilek","5 g badem dilimi"],"steps":["Chia, süt, kakao ve balı kavanozda iyice karıştırın.","10 dakika sonra topaklanmaması için bir kez daha karıştırın.","Buzdolabında en az 3 saat bekletin.","Doğranmış çilek ve bademle servis edin."]},{"id":"kah-16","category":"kahvalti","title":"Orman Meyveli Smoothie Kase","fit":true,"desc":"Dondurulmuş meyve ve yoğurttan yapılan koyu kıvamlı, üzeri granola ve tohumlarla süslü serinletici kase.","time":10,"servings":1,"difficulty":"Kolay","kcal":335,"protein":16,"carbs":50,"fat":8,"tags":["fit","pişirmesiz","vejetaryen"],"ingredients":["120 g dondurulmuş orman meyvesi","1/2 adet dondurulmuş muz","150 g süzme yoğurt","50 ml süt","15 g yulaf ezmesi","1 tatlı kaşığı keten tohumu","Birkaç dilim kivi"],"steps":["Dondurulmuş meyve, muz, yoğurt ve sütü blendera alın.","Koyu, kaşıkla yenecek kıvama gelene dek kısa aralıklarla çekin.","Kaseye aktarın.","Üzerine yulaf, keten tohumu ve kivi dilimlerini dizip hemen servis edin."]},{"id":"kah-17","category":"kahvalti","title":"Lorlu Sebzeli Yumurta Muffin","fit":true,"desc":"Muffin kalıbında pişen, önceden hazırlanıp saklanabilen proteinli mini omletler.","time":30,"servings":3,"difficulty":"Kolay","kcal":180,"protein":18,"carbs":5,"fat":10,"tags":["fit","hazırla-sakla","yüksek protein"],"ingredients":["6 adet yumurta","120 g lor peyniri","1 adet yeşil biber","1 adet küçük domates","3 dal taze soğan","1/2 demet dereotu","1 çay kaşığı zeytinyağı","1/2 çay kaşığı tuz"],"steps":["Fırını 180°C'ye ısıtın, 6'lı muffin kalıbını zeytinyağıyla yağlayın.","Sebzeleri ve dereotunu ince doğrayın.","Yumurtaları tuzla çırpıp lor ve sebzeleri ekleyin.","Karışımı kalıplara paylaştırıp 20 dakika, üzeri kabarıp pişene dek fırınlayın.","Ilınınca kalıptan çıkarın; kişi başı 2 adet hesaplayın."]},{"id":"kah-18","category":"kahvalti","title":"Yoğurtlu Granola Parfe","fit":true,"desc":"Süzme yoğurt, ev yapımı yulaf granola ve taze meyvenin katman katman dizildiği pratik kupa.","time":10,"servings":1,"difficulty":"Kolay","kcal":305,"protein":20,"carbs":36,"fat":9,"tags":["fit","pişirmesiz","yüksek protein"],"ingredients":["200 g süzme yoğurt","30 g yulaf ezmesi","80 g yaban mersini veya çilek","1 tatlı kaşığı bal","8 g fındık içi","1/2 çay kaşığı tarçın"],"steps":["Yulafı kuru tavada tarçınla 3 dakika hafifçe kavurun.","Fındıkları iri kırıp yulafa karıştırın.","Kupaya sırasıyla yoğurt, meyve ve yulaf karışımını katmanlar halinde dizin.","En üste bal gezdirip servis edin."]},{"id":"kah-19","category":"kahvalti","title":"Hindi Fümeli Tam Buğday Sandviç","fit":true,"desc":"Tam buğday ekmeği arasında hindi füme, labne ve bol yeşillikle dengeli ve taşınabilir kahvaltı.","time":10,"servings":1,"difficulty":"Kolay","kcal":305,"protein":24,"carbs":32,"fat":9,"tags":["fit","taşınabilir","hızlı"],"ingredients":["2 dilim tam buğday ekmeği","50 g hindi füme","30 g light labne","1 avuç roka","3 dilim salatalık","2 dilim domates","1 tutam kekik"],"steps":["Ekmekleri isteğe göre hafifçe kızartın.","Bir dilime labneyi sürüp kekik serpin.","Hindi füme, roka, salatalık ve domatesi dizin.","Diğer dilimle kapatıp çapraz keserek servis edin."]},{"id":"kah-20","category":"kahvalti","title":"Ispanaklı Yeşil Smoothie","fit":true,"desc":"Ispanak, elma, muz ve yoğurdun buluştuğu, iş yolunda içilebilecek ferah bir kahvaltı içeceği.","time":5,"servings":1,"difficulty":"Kolay","kcal":260,"protein":12,"carbs":42,"fat":5,"tags":["fit","pişirmesiz","içecek"],"ingredients":["1 avuç taze ıspanak","1/2 adet yeşil elma","1/2 adet muz","150 g yoğurt","100 ml su","1 tatlı kaşığı keten tohumu","Birkaç yaprak nane"],"steps":["Ispanağı yıkayın, elmanın çekirdeklerini çıkarıp doğrayın.","Tüm malzemeleri blendera alın.","Pürüzsüz olana kadar 1 dakika çekin.","Kıvamı suyla ayarlayıp hemen servis edin."]},{"id":"ana-01","category":"ana","title":"Karnıyarık","fit":false,"desc":"Közlenmiş gibi yumuşacık patlıcanlar, domatesli kıymalı harçla fırında buluşuyor.","time":60,"servings":4,"difficulty":"Orta","kcal":455,"protein":22,"carbs":20,"fat":32,"tags":["Et","Fırın","Klasik"],"ingredients":["4 adet orta boy patlıcan","250 g dana kıyma","1 adet kuru soğan","2 adet sivri biber","2 adet domates","2 diş sarımsak","1 yemek kaşığı domates salçası","3 yemek kaşığı zeytinyağı","1 çay kaşığı tuz","1/2 çay kaşığı karabiber"],"steps":["Patlıcanları alacalı soyun, tuzlu suda 15 dakika bekletip kurulayın.","Patlıcanları az yağda her yanı yumuşayana kadar çevirerek pişirin ya da fırında 20 dakika közleyin.","Soğanı kavurun, kıymayı ekleyip suyunu çekene dek pişirin; biber, sarımsak, domates ve salçayı ilave edin.","Patlıcanların ortasını kaşıkla açın ve harcı içlerine paylaştırın.","Üzerine biber ve domates dilimleri koyun, yarım çay kaşığı salçalı suyu tabana dökün.","180°C fırında 25 dakika pişirip pilavla servis edin."]},{"id":"ana-02","category":"ana","title":"İzmir Köfte","fit":false,"desc":"Patates, biber ve domatesle fırında pişen, sosuna ekmek bandırmalık bir ev klasiği.","time":65,"servings":4,"difficulty":"Orta","kcal":440,"protein":26,"carbs":30,"fat":24,"tags":["Köfte","Fırın","Klasik"],"ingredients":["400 g dana kıyma","1 adet rendelenmiş soğan","1 dilim bayat ekmek içi","1 adet yumurta","3 adet orta boy patates","3 adet sivri biber","2 adet domates","1 yemek kaşığı domates salçası","2 yemek kaşığı zeytinyağı","1 çay kaşığı kimyon","Tuz, karabiber"],"steps":["Kıyma, soğan, ekmek içi, yumurta, kimyon, tuz ve karabiberi 5 dakika yoğurun.","Harçtan parmak şeklinde köfteler yapıp tavada iki yüzünü hafifçe mühürleyin.","Patatesleri elma dilim kesip yağla harmanlayın ve 200°C fırında 15 dakika ön pişirin.","Tepsiye köfte, patates, biber ve domates dilimlerini sırayla dizin.","Salçayı 1,5 su bardağı sıcak suda eritip tepsiye dökün.","180°C fırında 30 dakika, patatesler yumuşayana kadar pişirin."]},{"id":"ana-03","category":"ana","title":"Etli Nohut","fit":false,"desc":"Kuşbaşı etle ağır ateşte pişen, tereyağı kokulu doyurucu nohut yemeği.","time":90,"servings":4,"difficulty":"Orta","kcal":410,"protein":28,"carbs":38,"fat":16,"tags":["Et","Bakliyat","Klasik"],"ingredients":["300 g kuşbaşı dana eti","400 g haşlanmış nohut","1 adet kuru soğan","1 yemek kaşığı domates salçası","1 yemek kaşığı biber salçası","1 yemek kaşığı tereyağı","1 yemek kaşığı zeytinyağı","5 su bardağı sıcak su","1 çay kaşığı pul biber","Tuz"],"steps":["Etleri tencerede yağ ile suyunu salıp çekene kadar kavurun.","Doğranmış soğanı ekleyip pembeleşene kadar çevirin.","Salçaları ve pul biberi ilave edip kokusu çıkana kadar kavurun.","Sıcak suyu ekleyin, kapağı kapalı kısık ateşte et yumuşayana kadar 45 dakika pişirin.","Nohutları ve tuzu ekleyip 20 dakika daha pişirin.","Tereyağını en son ekleyip bulgur pilavıyla servis edin."]},{"id":"ana-04","category":"ana","title":"Tavuk Sote","fit":false,"desc":"Renkli biberler ve domatesle tavada hızlıca pişen, sulu ve lezzetli tavuk sote.","time":35,"servings":4,"difficulty":"Kolay","kcal":285,"protein":30,"carbs":10,"fat":14,"tags":["Tavuk","Tava","Pratik"],"ingredients":["500 g tavuk but, kuşbaşı","1 adet kuru soğan","1 adet kırmızı biber","2 adet sivri biber","2 adet domates","1 yemek kaşığı biber salçası","2 diş sarımsak","2 yemek kaşığı zeytinyağı","1 çay kaşığı kekik","Tuz, karabiber"],"steps":["Tavayı yağla iyice ısıtın, tavukları ekleyip suyunu çekene kadar yüksek ateşte soteleyin.","Soğanı ve sarımsağı ekleyip 3 dakika çevirin.","Biberleri ekleyin ve hafif diriliklerini koruyarak 5 dakika pişirin.","Salçayı ve rendelenmiş domatesleri ilave edin.","Kekik, tuz ve karabiberle tatlandırıp kapağı kapalı 10 dakika pişirin."]},{"id":"ana-05","category":"ana","title":"Fırında Lazanya","fit":false,"desc":"Kat kat kıymalı sos, beşamel ve eriyen peynirle hazırlanan fırın klasiği.","time":90,"servings":6,"difficulty":"Zor","kcal":545,"protein":30,"carbs":48,"fat":26,"tags":["Makarna","Fırın","Dünya mutfağı"],"ingredients":["250 g lazanya yaprağı","400 g dana kıyma","1 adet kuru soğan","400 g domates püresi","2 diş sarımsak","40 g tereyağı","40 g un","600 ml süt","150 g rendelenmiş kaşar peyniri","1 çay kaşığı kuru fesleğen","Tuz, karabiber, muskat"],"steps":["Soğan ve sarımsağı kavurun, kıymayı ekleyip pişirin; domates püresi ve fesleğenle 20 dakika koyulaştırın.","Tereyağında unu kavurun, sütü azar azar ekleyip çırparak beşamel hazırlayın; tuz ve muskat ekleyin.","Fırın kabının tabanına biraz sos sürüp lazanya yapraklarını dizin.","Üzerine kıymalı sos ve beşamel yayın; bu katları malzemeler bitene kadar tekrarlayın.","En üste beşamel ve kaşar serpin.","Folyoyla örtüp 180°C fırında 25 dakika, folyoyu açıp 15 dakika daha pişirin; 10 dakika dinlendirin."]},{"id":"ana-06","category":"ana","title":"Kremalı Tavuk Köri","fit":false,"desc":"Hindistan cevizi sütü ve baharatlarla kadifemsi kıvamda, pirinçle harika eşleşen köri.","time":40,"servings":4,"difficulty":"Orta","kcal":385,"protein":30,"carbs":12,"fat":24,"tags":["Tavuk","Baharatlı","Dünya mutfağı"],"ingredients":["500 g tavuk göğsü, küp doğranmış","1 adet kuru soğan","3 diş sarımsak","1 yemek kaşığı rendelenmiş taze zencefil","2 yemek kaşığı köri tozu","1 çay kaşığı zerdeçal","200 ml hindistan cevizi sütü","200 g küp doğranmış domates","2 yemek kaşığı sıvı yağ","Taze kişniş, tuz"],"steps":["Yağda soğanı yumuşayana kadar kavurun, sarımsak ve zencefili ekleyin.","Köri tozu ve zerdeçalı ekleyip 1 dakika kavurarak aromasını açın.","Tavukları ilave edip her yüzü beyazlaşana kadar çevirin.","Domatesleri ekleyip 5 dakika pişirin.","Hindistan cevizi sütünü dökün, kısık ateşte 15 dakika koyulaşana kadar pişirin.","Tuzunu ayarlayıp kişnişle süsleyin, basmati pirinçle servis edin."]},{"id":"ana-07","category":"ana","title":"Dana Stroganoff","fit":false,"desc":"İnce şeritler halinde dana eti, mantar ve ekşi krema ile hazırlanan zengin bir tava yemeği.","time":35,"servings":4,"difficulty":"Orta","kcal":400,"protein":32,"carbs":10,"fat":26,"tags":["Et","Tava","Dünya mutfağı"],"ingredients":["500 g dana bonfile, şerit doğranmış","250 g kültür mantarı","1 adet kuru soğan","2 diş sarımsak","200 g ekşi krema","1 tatlı kaşığı hardal","1 yemek kaşığı un","20 g tereyağı","1 yemek kaşığı sıvı yağ","Tuz, karabiber, maydanoz"],"steps":["Etleri tuz, karabiber ve unla harmanlayın.","Çok kızgın tavada yağ ile etleri partiler halinde 2 dakika mühürleyip alın.","Aynı tavada tereyağında soğan, sarımsak ve mantarları suyunu çekene kadar soteleyin.","Hardal ve ekşi kremayı ekleyip karıştırın, kaynatmadan ısıtın.","Etleri geri ekleyip 2 dakika sosla buluşturun; maydanozla servis edin."]},{"id":"ana-08","category":"ana","title":"Spagetti Bolonez","fit":false,"desc":"Uzun süre pişirilen yoğun domatesli kıyma sosuyla her lokması doyurucu bir makarna.","time":60,"servings":4,"difficulty":"Orta","kcal":545,"protein":28,"carbs":68,"fat":18,"tags":["Makarna","Et","Dünya mutfağı"],"ingredients":["320 g spagetti","350 g dana kıyma","1 adet kuru soğan","1 adet havuç, ince doğranmış","1 sap kereviz, ince doğranmış","2 diş sarımsak","400 g domates püresi","1 yemek kaşığı domates salçası","2 yemek kaşığı zeytinyağı","1 çay kaşığı kekik","40 g rendelenmiş parmesan tipi sert peynir"],"steps":["Zeytinyağında soğan, havuç ve kereviz yumuşayana kadar kavurun.","Sarımsak ve kıymayı ekleyip kıyma iyice renk alana kadar pişirin.","Salça, domates püresi, kekik, tuz ve karabiberi ilave edin.","Kapağı aralık, kısık ateşte ara ara karıştırarak 35 dakika pişirin.","Spagettiyi tuzlu suda al dente haşlayıp süzün.","Makarnayı sosla karıştırın, üzerine rendelenmiş peynir serperek servis edin."]},{"id":"ana-09","category":"ana","title":"Tavuklu Milföy Turta","fit":false,"desc":"Kremalı tavuk ve sebze harcının çıtır milföy kapakla fırınlandığı sıcacık bir turta.","time":70,"servings":6,"difficulty":"Orta","kcal":490,"protein":24,"carbs":36,"fat":28,"tags":["Tavuk","Fırın","Dünya mutfağı"],"ingredients":["500 g haşlanmış tavuk göğsü, didiklenmiş","1 adet kuru soğan","1 adet havuç, küp doğranmış","100 g bezelye","150 g mantar","30 g tereyağı","2 yemek kaşığı un","300 ml tavuk suyu","200 ml süt","1 paket (yaklaşık 400 g) milföy hamuru","1 adet yumurta sarısı"],"steps":["Tereyağında soğan, havuç ve mantarı 5 dakika soteleyin.","Unu ekleyip 1 dakika kavurun; tavuk suyu ve sütü çırparak ekleyin.","Sos koyulaşınca tavuk, bezelye, tuz ve karabiberi ilave edip ocaktan alın.","Harcı fırın kabına yayın, üzerini milföy hamuruyla kapatıp kenarlarını bastırın.","Hamurun üstüne yumurta sarısı sürün ve buhar çıkması için birkaç çizik atın.","200°C fırında hamur kabarıp altın rengi olana kadar 30-35 dakika pişirin."]},{"id":"ana-10","category":"ana","title":"Kıymalı Taco","fit":false,"desc":"Baharatlı kıyma, taze domates ve yoğurt sosuyla doldurulan eğlenceli ve renkli tacolar.","time":30,"servings":4,"difficulty":"Kolay","kcal":440,"protein":26,"carbs":34,"fat":22,"tags":["Et","Dünya mutfağı","Pratik"],"ingredients":["8 adet küçük mısır tortillası","400 g dana kıyma","1 adet kuru soğan","1 çay kaşığı kimyon","1 çay kaşığı toz kırmızı biber","1/2 çay kaşığı kekik","2 adet domates, küp doğranmış","2 yaprak marul, ince kıyılmış","100 g süzme yoğurt","60 g rendelenmiş kaşar peyniri","1/2 adet limon"],"steps":["Soğanı tavada kavurun, kıymayı ekleyip suyunu çekene kadar pişirin.","Kimyon, kırmızı biber, kekik ve tuzu ekleyip 3 dakika daha pişirin.","Tortillaları kuru tavada her yüzü 30 saniye ısıtın.","Yoğurdu limon suyu ve bir tutam tuzla karıştırarak sos hazırlayın.","Tortillalara kıyma, marul, domates, peynir ve yoğurt sosu koyarak katlayıp servis edin."]},{"id":"ana-11","category":"ana","title":"Hünkar Beğendi","fit":false,"desc":"Közlenmiş patlıcanlı kremsi beğendi yatağında, yumuşacık pişmiş et yahnisi.","time":100,"servings":4,"difficulty":"Zor","kcal":495,"protein":30,"carbs":22,"fat":32,"tags":["Et","Klasik","Özel gün"],"ingredients":["500 g kuşbaşı kuzu eti","1 adet kuru soğan","2 adet domates","1 yemek kaşığı domates salçası","1 kg patlıcan","30 g tereyağı","2 yemek kaşığı un","300 ml süt","60 g rendelenmiş kaşar peyniri","Tuz, karabiber"],"steps":["Eti tencerede kendi suyunu çekene kadar kavurun, soğanı ekleyip pembeleştirin.","Salça ve rendelenmiş domatesi ekleyin, sıcak su ilave edip kısık ateşte et yumuşayana kadar 60 dakika pişirin.","Patlıcanları ocakta ya da fırında közleyin, kabuklarını soyup ince kıyın.","Tereyağında unu kavurun, sütü azar azar ekleyerek koyu bir sos hazırlayın.","Patlıcanları sosa ekleyip 5 dakika pişirin, kaşar peynirini ekleyip eritin.","Beğendiyi tabağa yayın, ortasına et yahnisini koyarak sıcak servis edin."]},{"id":"ana-12","category":"ana","title":"Orman Kebabı","fit":false,"desc":"Kuşbaşı et, bezelye, havuç ve patatesle tencerede ağır ağır pişen doyurucu kebap.","time":90,"servings":4,"difficulty":"Orta","kcal":395,"protein":28,"carbs":26,"fat":20,"tags":["Et","Tencere","Klasik"],"ingredients":["500 g kuşbaşı dana eti","2 adet orta boy patates","1 adet havuç","100 g bezelye","12 adet arpacık soğan","2 adet domates","1 yemek kaşığı domates salçası","2 yemek kaşığı zeytinyağı","1 defne yaprağı","Tuz, karabiber, kekik"],"steps":["Etleri zeytinyağında suyunu salıp çekene kadar kavurun.","Arpacık soğanları ekleyip hafifçe renk alana kadar çevirin.","Salça ve rendelenmiş domatesi ekleyip 3 dakika pişirin.","2 su bardağı sıcak su ve defne yaprağını ekleyip kısık ateşte 40 dakika pişirin.","Küp patates, havuç ve bezelyeyi ilave edin, sebzeler yumuşayana kadar 25 dakika daha pişirin.","Kekik ve karabiberle tatlandırıp servis edin."]},{"id":"ana-13","category":"ana","title":"Tavuk Göğsü ve Limonlu Kinoa","fit":true,"desc":"Izgara tavuk göğsü, taze otlu limonlu kinoa ve sebzelerle dengeli bir tabak.","time":35,"servings":2,"difficulty":"Kolay","kcal":435,"protein":42,"carbs":40,"fat":12,"tags":["Tavuk","Yüksek protein","Fit"],"ingredients":["300 g tavuk göğsü","100 g çiğ kinoa","1 adet salatalık","10 adet çeri domates","1/2 demet maydanoz","1 adet limon","1 yemek kaşığı zeytinyağı","1 diş sarımsak","1 çay kaşığı toz kırmızı biber","Tuz, karabiber"],"steps":["Kinoayı iyice yıkayın, 2 katı suda kapağı kapalı 15 dakika pişirip soğumaya bırakın.","Tavuğu yarım limon suyu, sarımsak, kırmızı biber, tuz ve karabiberle 10 dakika marine edin.","Izgara tavada tavuğu her yüzünü 6-7 dakika pişirip 5 dakika dinlendirin.","Kinoaya doğranmış salatalık, domates, maydanoz, kalan limon suyu ve zeytinyağını ekleyin.","Tavuğu dilimleyip kinoanın üzerine yerleştirerek servis edin."]},{"id":"ana-14","category":"ana","title":"Fırında Hindi Köfte","fit":true,"desc":"Az yağlı hindi kıymasından, taze otlarla hazırlanmış yumuşacık fırın köftesi.","time":35,"servings":4,"difficulty":"Kolay","kcal":275,"protein":32,"carbs":14,"fat":10,"tags":["Köfte","Yüksek protein","Fit"],"ingredients":["500 g hindi kıyması","1 adet rendelenmiş kuru soğan","40 g yulaf ezmesi","1 adet yumurta","1/2 demet maydanoz","2 diş sarımsak","1 çay kaşığı kimyon","1 çay kaşığı pul biber","1 yemek kaşığı zeytinyağı","Tuz, karabiber"],"steps":["Fırını 200°C'ye ısıtın, tepsiye pişirme kağıdı serin.","Tüm malzemeleri geniş bir kapta 5 dakika yoğurun.","Harcı 20 dakika buzdolabında dinlendirin.","Nemli elle ceviz büyüklüğünde köfteler yapıp tepsiye dizin, üzerlerine hafifçe yağ sürün.","18-20 dakika, köfteler kızarana kadar pişirin; yoğurt ve salatayla servis edin."]},{"id":"ana-15","category":"ana","title":"Sebzeli Bulgur Pilavı","fit":true,"desc":"Kabak, biber ve havuçla zenginleşen, lif dolu ve tane tane bulgur pilavı.","time":35,"servings":4,"difficulty":"Kolay","kcal":330,"protein":9,"carbs":56,"fat":8,"tags":["Vejetaryen","Lifli","Fit"],"ingredients":["200 g pilavlık bulgur","1 adet kuru soğan","1 adet kabak","1 adet havuç","1 adet kırmızı biber","1 yemek kaşığı biber salçası","1,5 yemek kaşığı zeytinyağı","500 ml sıcak su","1 çay kaşığı nane","Tuz, karabiber"],"steps":["Soğanı zeytinyağında yumuşayana kadar kavurun.","Küp doğranmış havuç, biber ve kabağı ekleyip 5 dakika soteleyin.","Salçayı ekleyip kokusu çıkana kadar çevirin.","Bulguru ekleyip 2 dakika kavurun, sıcak su, tuz ve baharatları ilave edin.","Kapağı kapalı kısık ateşte suyunu çekene kadar 15 dakika pişirin, 10 dakika demlendirin."]},{"id":"ana-16","category":"ana","title":"Mercimek Köftesi","fit":true,"desc":"Kırmızı mercimek ve ince bulgurla hazırlanan, marul yaprağında servis edilen hafif köfte.","time":45,"servings":6,"difficulty":"Kolay","kcal":295,"protein":12,"carbs":48,"fat":6,"tags":["Vejetaryen","Bakliyat","Fit"],"ingredients":["200 g kırmızı mercimek","150 g köftelik ince bulgur","1 adet kuru soğan","2 yemek kaşığı zeytinyağı","1 yemek kaşığı biber salçası","1 demet yeşil soğan","1/2 demet maydanoz","1 çay kaşığı kimyon","1 çay kaşığı pul biber","1 adet limon","Marul yaprakları"],"steps":["Mercimeği 3 su bardağı suda dağılana kadar yaklaşık 15 dakika haşlayın.","Ocaktan alıp sıcakken bulguru ekleyin, kapağı kapatıp 15 dakika demlendirin.","Soğanı zeytinyağında kavurun, salçayı ekleyip mercimeğe ilave edin.","Kimyon, pul biber, tuz ve limon suyunu ekleyip ılıyınca iyice yoğurun.","İnce kıyılmış yeşillikleri ekleyip elle sıkarak köfteler şekillendirin.","Marul yaprakları ve limon dilimleriyle servis edin."]},{"id":"ana-17","category":"ana","title":"Fit Lahmacun","fit":true,"desc":"Tam buğday hamurunda yağsız kıymalı harçla evde çıtır, hafif bir lahmacun.","time":50,"servings":4,"difficulty":"Orta","kcal":355,"protein":24,"carbs":44,"fat":9,"tags":["Et","Tam buğday","Fit"],"ingredients":["200 g tam buğday unu","5 g kuru maya","150 ml ılık su","200 g az yağlı dana kıyma","1 adet kuru soğan","1 adet domates","1 adet kırmızı biber","1/2 demet maydanoz","1 yemek kaşığı biber salçası","1 çay kaşığı pul biber","Tuz, limon"],"steps":["Un, maya, tuz ve ılık suyu yoğurup 30 dakika mayalanmaya bırakın.","Soğan, domates, biber ve maydanozu robotta çekin; kıyma, salça, pul biber ve tuzla karıştırın.","Hamuru 4 bezeye ayırıp çok ince açın.","Harcı hamurların üzerine ince bir tabaka halinde yayın.","Önceden 250°C'ye ısıtılmış fırında 8-10 dakika kenarları kızarana kadar pişirin.","Maydanoz ve limonla servis edin."]},{"id":"ana-18","category":"ana","title":"Fırında Tavuk Şiş ve Sebze","fit":true,"desc":"Yoğurtlu marine tavuk küpleri ve renkli sebzelerle tek tepside hafif akşam yemeği.","time":40,"servings":3,"difficulty":"Kolay","kcal":315,"protein":38,"carbs":18,"fat":10,"tags":["Tavuk","Fırın","Yüksek protein","Fit"],"ingredients":["450 g tavuk göğsü, küp doğranmış","100 g yoğurt","1 yemek kaşığı biber salçası","1 yemek kaşığı zeytinyağı","1 adet kırmızı biber","1 adet yeşil biber","1 adet kabak","1 adet kırmızı soğan","2 diş sarımsak","1 çay kaşığı kekik","Tuz, karabiber"],"steps":["Yoğurt, salça, sarımsak, kekik, tuz ve karabiberi karıştırıp tavuğu en az 20 dakika marine edin.","Sebzeleri iri parçalar halinde doğrayıp zeytinyağıyla harmanlayın.","Tavuk ve sebzeleri tahta şişlere dönüşümlü dizin.","Şişleri pişirme kağıdı serili tepsiye yerleştirin.","220°C fırında 20-25 dakika, yarısında çevirerek pişirin."]},{"id":"ana-19","category":"ana","title":"Fırında Kabak Musakka","fit":true,"desc":"Patlıcan yerine ince kabak dilimleri ve yağsız kıymayla hazırlanmış hafif musakka.","time":55,"servings":4,"difficulty":"Orta","kcal":295,"protein":26,"carbs":16,"fat":14,"tags":["Et","Fırın","Düşük karbonhidrat","Fit"],"ingredients":["3 adet orta boy kabak","300 g az yağlı dana kıyma","1 adet kuru soğan","2 adet domates","1 adet yeşil biber","1 yemek kaşığı domates salçası","1 yemek kaşığı zeytinyağı","150 g yoğurt","1 adet yumurta","40 g rendelenmiş kaşar peyniri","Tuz, karabiber"],"steps":["Kabakları uzunlamasına dilimleyip tuzlayın ve fırında 10 dakika ön pişirin.","Soğanı zeytinyağında kavurun, kıymayı ekleyip pişirin.","Biber, domates ve salçayı ekleyip 10 dakika koyulaştırın.","Fırın kabına kabak ve kıymalı harcı kat kat dizin.","Yoğurt, yumurta ve peyniri çırpıp üzerine yayın.","190°C fırında 25 dakika, üstü kızarana kadar pişirin."]},{"id":"ana-20","category":"ana","title":"Izgara Bonfile ve Fırın Sebze","fit":true,"desc":"Mühürlenmiş dana bonfile, fırında karamelize brokoli ve tatlı patatesle protein dolu tabak.","time":40,"servings":2,"difficulty":"Orta","kcal":430,"protein":40,"carbs":32,"fat":16,"tags":["Et","Yüksek protein","Fit"],"ingredients":["350 g dana bonfile","250 g brokoli","1 adet orta boy tatlı patates","1 adet kırmızı soğan","1 yemek kaşığı zeytinyağı","2 diş sarımsak","2 dal taze biberiye","1 çay kaşığı hardal","Tuz, iri çekilmiş karabiber"],"steps":["Tatlı patatesi küp, soğanı iri doğrayın; brokoliyle birlikte yarım kaşık zeytinyağı ve tuzla harmanlayın.","Sebzeleri 210°C fırında 25 dakika pişirin.","Bonfileyi oda ısısına getirip tuz, karabiber ve hardalla ovun.","Döküm tavayı çok iyi ısıtın, kalan yağla bonfileyi her yüzü 3-4 dakika mühürleyin.","Son dakikada sarımsak ve biberiyeyi tavaya ekleyip etin üzerine gezdirin.","Eti 5 dakika dinlendirip dilimleyin ve sebzelerle servis edin."]},{"id":"ana-21","category":"ana","title":"Tavuklu Karnabahar Pilavı","fit":true,"desc":"Pirinç yerine rendelenmiş karnabaharla hazırlanan, Uzak Doğu esintili düşük karbonhidratlı tava.","time":30,"servings":2,"difficulty":"Kolay","kcal":335,"protein":36,"carbs":16,"fat":14,"tags":["Tavuk","Düşük karbonhidrat","Fit"],"ingredients":["300 g tavuk göğsü, küp doğranmış","1 adet orta boy karnabahar","2 adet yumurta","1 adet havuç, küçük küp","80 g bezelye","3 dal yeşil soğan","2 diş sarımsak","1 yemek kaşığı rendelenmiş taze zencefil","2 yemek kaşığı az tuzlu soya sosu","2 çay kaşığı susam yağı"],"steps":["Karnabaharı rondoda pirinç tanesi büyüklüğünde çekin.","Geniş tavada yarım yağla tavukları pişirip bir kenara alın.","Kalan yağda sarımsak, zencefil, havuç ve bezelyeyi 4 dakika soteleyin.","Karnabaharı ekleyip yüksek ateşte 5 dakika çevirin.","Tavanın bir kenarında yumurtaları çırpıp karıştırarak pişirin.","Tavuk, soya sosu ve yeşil soğanı ekleyip karıştırarak servis edin."]},{"id":"ana-22","category":"ana","title":"Tavada Tavuk Fajita","fit":true,"desc":"Baharatlı tavuk şeritleri ve renkli biberlerle tam buğday lavaşta pratik akşam yemeği.","time":25,"servings":4,"difficulty":"Kolay","kcal":380,"protein":34,"carbs":36,"fat":11,"tags":["Tavuk","Pratik","Fit"],"ingredients":["500 g tavuk göğsü, şerit doğranmış","1 adet kırmızı biber","1 adet sarı biber","1 adet kırmızı soğan","1 yemek kaşığı zeytinyağı","1 çay kaşığı kimyon","1 çay kaşığı tatlı toz kırmızı biber","1 adet limon","4 adet küçük tam buğday lavaş","100 g süzme yoğurt","Taze kişniş, tuz"],"steps":["Tavuğu kimyon, kırmızı biber, limon suyu ve tuzla harmanlayın.","Tavayı ısıtıp yarım kaşık yağla tavukları yüksek ateşte 6-7 dakika pişirin ve alın.","Kalan yağda şerit biber ve soğanları diri kalacak şekilde 4 dakika soteleyin.","Tavukları tavaya geri ekleyip karıştırın.","Isıtılmış lavaşlara yoğurt sürüp tavuklu harcı koyun, kişnişle servis edin."]},{"id":"ana-23","category":"ana","title":"Tepside Sebzeli Fit Köfte","fit":true,"desc":"Yağsız kıymalı köfteler, kabak, patlıcan ve domatesle tek tepside fırınlanıyor.","time":50,"servings":4,"difficulty":"Kolay","kcal":310,"protein":28,"carbs":18,"fat":14,"tags":["Köfte","Fırın","Fit"],"ingredients":["400 g az yağlı dana kıyma","1 adet rendelenmiş kuru soğan","30 g yulaf ezmesi","1 adet yumurta akı","1 adet kabak","1 adet patlıcan","2 adet domates","2 adet sivri biber","1 yemek kaşığı zeytinyağı","1 çay kaşığı kimyon","Tuz, karabiber, kekik"],"steps":["Kıyma, soğan, yulaf, yumurta akı, kimyon, tuz ve karabiberi yoğurun.","Harçtan yassı köfteler şekillendirin.","Kabak, patlıcan ve domatesi halka, biberleri ikiye bölerek doğrayın.","Sebzeleri zeytinyağı ve kekikle harmanlayıp tepsiye yayın, köfteleri aralarına yerleştirin.","Yarım su bardağı su ekleyip 200°C fırında 30-35 dakika pişirin."]},{"id":"ana-24","category":"ana","title":"Hindi Kıymalı Biber Dolması","fit":true,"desc":"Hindi kıyması ve bulgurlu iç harçla doldurulmuş, yoğurtla servis edilen hafif dolma.","time":60,"servings":4,"difficulty":"Orta","kcal":290,"protein":24,"carbs":30,"fat":8,"tags":["Dolma","Yüksek protein","Fit"],"ingredients":["8 adet dolmalık biber","300 g hindi kıyması","80 g pilavlık bulgur","1 adet kuru soğan, ince doğranmış","1 adet domates, rendelenmiş","1 yemek kaşığı domates salçası","1/2 demet maydanoz","1 yemek kaşığı kuru nane","1 yemek kaşığı zeytinyağı","Tuz, karabiber, pul biber"],"steps":["Biberlerin kapaklarını kesip çekirdeklerini temizleyin.","Kıyma, yıkanmış bulgur, soğan, domates, yarım kaşık salça, maydanoz, nane ve baharatları karıştırın.","Harcı biberlere dörtte üçünü dolduracak şekilde koyup kapaklarını kapatın.","Biberleri tencereye dik dizin; kalan salçayı 2 su bardağı sıcak su ve zeytinyağıyla karıştırıp dökün.","Kapağı kapalı kısık ateşte 40 dakika pişirin; yoğurtla servis edin."]},{"id":"ana-25","category":"ana","title":"Fırında Yoğurtlu Tavuk But","fit":true,"desc":"Baharatlı yoğurda yatırılmış derisiz tavuk butları, fırında yumuşacık ve kızarmış.","time":55,"servings":4,"difficulty":"Kolay","kcal":295,"protein":34,"carbs":8,"fat":14,"tags":["Tavuk","Fırın","Yüksek protein","Fit"],"ingredients":["800 g derisiz kemikli tavuk but","150 g yoğurt","1 yemek kaşığı biber salçası","1 yemek kaşığı zeytinyağı","3 diş sarımsak","1 çay kaşığı tatlı toz kırmızı biber","1 çay kaşığı kekik","1/2 çay kaşığı kimyon","1/2 adet limon","Tuz, karabiber"],"steps":["Yoğurt, salça, zeytinyağı, sarımsak, limon suyu ve baharatları karıştırın.","Tavuk butlarına birkaç çizik atıp marinata bulayın, en az 1 saat buzdolabında bekletin.","Butları pişirme kağıdı serili tepsiye aralıklı dizin.","200°C fırında 35-40 dakika, üzeri kızarana kadar pişirin.","Bulgur pilavı ya da bol yeşil salatayla servis edin."]},{"id":"ana-26","category":"ana","title":"Ezogelin Çorbası","fit":true,"desc":"Kırmızı mercimek, bulgur ve nane ile doyurucu, sıcacık ve lif dolu bir akşam çorbası.","time":40,"servings":4,"difficulty":"Kolay","kcal":250,"protein":11,"carbs":38,"fat":6,"tags":["Çorba","Vejetaryen","Lifli"],"ingredients":["150 g kırmızı mercimek","40 g ince bulgur","30 g pirinç","1 adet kuru soğan","1 yemek kaşığı domates salçası","1 yemek kaşığı zeytinyağı","1,5 litre sıcak su","1 tatlı kaşığı kuru nane","1 çay kaşığı pul biber","Tuz, karabiber"],"steps":["Mercimek, bulgur ve pirinci yıkayıp süzün.","Soğanı zeytinyağında pembeleşene kadar kavurun, salçayı ekleyip 1 dakika çevirin.","Tahılları ve sıcak suyu ekleyip kısık ateşte 30 dakika pişirin.","Mercimekler dağılınca naneyi, pul biberi, tuzu ve karabiberi ekleyin.","Limon eşliğinde sıcak servis edin."]},{"id":"ana-27","category":"ana","title":"Ev Tarhanası Çorbası","fit":false,"desc":"Ekşimsi tarhananın tereyağlı nane sosuyla buluştuğu, kış akşamlarının vazgeçilmezi.","time":25,"servings":4,"difficulty":"Kolay","kcal":220,"protein":7,"carbs":30,"fat":8,"tags":["Çorba","Geleneksel","Vejetaryen"],"ingredients":["80 g toz tarhana","1 litre su","1 yemek kaşığı domates salçası","1 yemek kaşığı zeytinyağı","20 g tereyağı","1 tatlı kaşığı kuru nane","1 çay kaşığı pul biber","2 diş sarımsak","Tuz"],"steps":["Tarhanayı 250 ml soğuk suyla açıp 10 dakika bekletin.","Zeytinyağında salçayı ve ezilmiş sarımsağı kısa süre kavurun.","Kalan suyu ekleyin, kaynayınca tarhanayı karıştırarak ilave edin.","Sürekli karıştırarak kısık ateşte 15 dakika pişirin, tuzlayın.","Tereyağını eritip nane ve pul biberle çorbanın üzerine gezdirin."]},{"id":"ana-28","category":"ana","title":"Sebzeli Minestrone","fit":true,"desc":"Bol sebze, beyaz fasulye ve kısa makarnayla renkli, tek kasede tam bir öğün.","time":45,"servings":4,"difficulty":"Kolay","kcal":262,"protein":10,"carbs":42,"fat":6,"tags":["Çorba","Vejetaryen","Lifli","Düşük Kalori"],"ingredients":["1 adet havuç","1 adet kabak","1 sap kereviz","1 adet kuru soğan","200 g haşlanmış beyaz fasulye","400 g doğranmış domates","60 g tam buğday kısa makarna","1 litre sebze suyu","1 yemek kaşığı zeytinyağı","1 avuç ıspanak","Kekik, tuz, karabiber"],"steps":["Soğan, havuç ve kerevizi küp doğrayıp zeytinyağında 5 dakika soteleyin.","Kabak ve domatesi ekleyip 5 dakika daha pişirin.","Sebze suyunu ekleyin, kaynayınca makarnayı atın.","10 dakika pişirdikten sonra fasulye ve ıspanağı ekleyin.","Kekik, tuz ve karabiberle tatlandırıp 3 dakika daha pişirin."]},{"id":"ana-29","category":"ana","title":"Tavuk Suyu Şehriye Çorbası","fit":true,"desc":"Kemik suyunda pişen didiklenmiş tavuk ve sebzelerle hem hafif hem proteinli bir öğün.","time":60,"servings":4,"difficulty":"Kolay","kcal":238,"protein":24,"carbs":22,"fat":6,"tags":["Çorba","Tavuk","Yüksek Protein"],"ingredients":["400 g kemikli tavuk but","1,5 litre su","1 adet havuç","1 adet kuru soğan","1 sap kereviz","50 g tel şehriye","1 yemek kaşığı zeytinyağı","1 adet limon","Maydanoz, tuz, karabiber"],"steps":["Tavuğu soğan ve kerevizle birlikte suda 35 dakika haşlayın, köpüğünü alın.","Tavuğu çıkarıp kemiklerinden ayırın ve didikleyin; suyu süzün.","Rendelenmiş havucu zeytinyağında çevirin, tavuk suyunu ekleyin.","Şehriyeyi ve tavuk etini ekleyip 10 dakika pişirin.","Tuz, karabiber, limon suyu ve kıyılmış maydanozla servis edin."]},{"id":"ana-30","category":"ana","title":"Ton Balıklı Doyurucu Salata","fit":true,"desc":"Ton balığı, haşlanmış yumurta ve yeşilliklerle hazırlanan 15 dakikalık proteinli öğün.","time":15,"servings":2,"difficulty":"Kolay","kcal":317,"protein":30,"carbs":20,"fat":13,"tags":["Balık","Salata","Yüksek Protein","Pratik"],"ingredients":["160 g süzülmüş suda ton balığı","2 adet haşlanmış yumurta","1 kase marul ve roka","150 g haşlanmış mısır ve nohut karışımı","1 adet salatalık","10 adet çeri domates","1/2 adet mor soğan","1 yemek kaşığı zeytinyağı","1 adet limon","Tuz, sumak"],"steps":["Yeşillikleri yıkayıp kurulayın ve iri doğrayın.","Salatalık, domates ve soğanı doğrayıp yeşilliklerle karıştırın.","Mısır-nohut karışımını ve ton balığını ekleyin.","Zeytinyağı, limon suyu, tuz ve sumakla sos hazırlayıp gezdirin.","Dörde bölünmüş yumurtaları üzerine yerleştirip servis edin."]},{"id":"ana-31","category":"ana","title":"Nohutlu Kinoa Salatası","fit":true,"desc":"Kinoa, nohut ve taze otların limonlu sosla buluştuğu bitkisel proteinli salata kasesi.","time":30,"servings":3,"difficulty":"Kolay","kcal":372,"protein":14,"carbs":52,"fat":12,"tags":["Vejetaryen","Salata","Lifli"],"ingredients":["150 g kinoa","250 g haşlanmış nohut","1 adet kırmızı biber","1 adet salatalık","1 demet maydanoz","Birkaç dal taze nane","2 adet taze soğan","1,5 yemek kaşığı zeytinyağı","1 adet limon","1 tatlı kaşığı nar ekşisi","Tuz, kimyon"],"steps":["Kinoayı iyice yıkayıp iki katı suda 15 dakika pişirin ve soğutun.","Biber, salatalık, taze soğan ve otları ince doğrayın.","Kinoa, nohut ve sebzeleri geniş bir kapta birleştirin.","Zeytinyağı, limon, nar ekşisi, tuz ve kimyonu çırpıp salataya ekleyin.","Buzdolabında 10 dakika dinlendirip servis edin."]},{"id":"ana-32","category":"ana","title":"Fit Tavuklu Sezar Salata","fit":true,"desc":"Izgara tavuk, çıtır tam buğday kruton ve yoğurtlu hafif sosla klasiğin fit yorumu.","time":30,"servings":2,"difficulty":"Kolay","kcal":341,"protein":38,"carbs":18,"fat":13,"tags":["Tavuk","Salata","Yüksek Protein"],"ingredients":["300 g tavuk göğsü","1 adet göbek marul","1 dilim tam buğday ekmeği","100 g süzme yoğurt","20 g rendelenmiş parmesan","1 diş sarımsak","1 tatlı kaşığı hardal","1 yemek kaşığı zeytinyağı","Yarım limon suyu","Tuz, karabiber"],"steps":["Tavuğu tuz, karabiber ve birkaç damla zeytinyağıyla ovup ızgarada her yüzünü 6 dakika pişirin.","Ekmeği küp doğrayıp fırında 8 dakika kızartarak kruton yapın.","Yoğurt, hardal, ezilmiş sarımsak, limon, kalan zeytinyağı ve parmesanın yarısını çırpın.","Marulu iri doğrayıp sosla harmanlayın.","Dilimlenmiş tavuk, kruton ve kalan parmesanla tabakları tamamlayın."]},{"id":"ana-33","category":"ana","title":"Levrek Buğulama","fit":true,"desc":"Domates, biber ve limonla kendi suyunda pişen yumuşacık, hafif levrek.","time":35,"servings":2,"difficulty":"Orta","kcal":284,"protein":34,"carbs":10,"fat":12,"tags":["Balık","Düşük Kalori","Yüksek Protein"],"ingredients":["2 adet levrek fileto (yaklaşık 320 g)","2 adet domates","2 adet sivri biber","1 adet kuru soğan","3 diş sarımsak","1 yemek kaşığı zeytinyağı","100 ml sıcak su","1 adet limon","Yarım demet dereotu","Tuz, karabiber"],"steps":["Soğanı piyazlık, sarımsağı dilim, biberi halka, domatesi küp doğrayın.","Geniş tavaya zeytinyağı ve soğanı koyup 3 dakika soteleyin.","Sebzeleri tabana yayıp üzerine tuzlanmış filetoları yerleştirin.","Limon dilimleri ve sıcak suyu ekleyip kapağı kapalı kısık ateşte 15 dakika pişirin.","Dereotu serpip tencereden alarak sıcak servis edin."]},{"id":"ana-34","category":"ana","title":"Karides Güveç","fit":false,"desc":"Fırında kaşarla gratine edilen tereyağlı, sarımsaklı ve biberli nefis karides güveç.","time":30,"servings":2,"difficulty":"Orta","kcal":338,"protein":32,"carbs":12,"fat":18,"tags":["Deniz Ürünü","Yüksek Protein","Fırın"],"ingredients":["300 g ayıklanmış karides","1 adet kırmızı biber","2 adet sivri biber","1 adet domates","4 diş sarımsak","20 g tereyağı","1 yemek kaşığı zeytinyağı","40 g rendelenmiş kaşar peyniri","1 çay kaşığı pul biber","Kekik, tuz"],"steps":["Fırını 200°C'ye ısıtın; biberleri ve domatesi küçük doğrayın.","Tavada tereyağı ve zeytinyağında sarımsağı 30 saniye kavurun.","Biberleri ekleyip 4 dakika soteleyin, ardından domatesi ilave edin.","Karidesleri ekleyin, 2 dakika çevirip baharatlarla tatlandırın.","Güveç kaplarına paylaştırıp kaşar serpin ve fırında 10 dakika kızartın."]},{"id":"ana-35","category":"ana","title":"Fit Balık Taco","fit":true,"desc":"Baharatlı fırın balığı, mor lahana ve yoğurtlu limon sosuyla hafif ve çıtır dürümler.","time":30,"servings":3,"difficulty":"Orta","kcal":338,"protein":28,"carbs":34,"fat":10,"tags":["Balık","Pratik","Yüksek Protein"],"ingredients":["400 g beyaz etli balık fileto","6 adet küçük tam buğday lavaş","150 g ince doğranmış mor lahana","1/2 adet avokado","120 g süzme yoğurt","1 adet limon","1 çay kaşığı kimyon","1 çay kaşığı tatlı toz biber","1 yemek kaşığı zeytinyağı","Maydanoz, tuz"],"steps":["Balığı kimyon, toz biber, tuz ve zeytinyağıyla ovun.","200°C fırında 12-15 dakika pişirip çatalla iri parçalara ayırın.","Yoğurdu limon suyu ve bir tutam tuzla çırparak sos hazırlayın.","Lavaşları kuru tavada ısıtın.","Lahana, balık, avokado dilimleri ve sosu lavaşlara yerleştirip maydanozla servis edin."]},{"id":"ana-36","category":"ana","title":"Zeytinyağlı Kuru Fasulye","fit":false,"desc":"Gece ıslatılmış fasulyenin salçalı sosta ağır ağır piştiği, pilavın sadık yoldaşı.","time":90,"servings":4,"difficulty":"Orta","kcal":339,"protein":15,"carbs":45,"fat":11,"tags":["Vejetaryen","Baklagil","Geleneksel"],"ingredients":["300 g kuru fasulye (bir gece ıslatılmış)","1 adet büyük kuru soğan","2 adet sivri biber","1 yemek kaşığı domates salçası","1 yemek kaşığı biber salçası","2 adet rendelenmiş domates","3 yemek kaşığı zeytinyağı","1 litre sıcak su","Tuz, pul biber"],"steps":["Islatılmış fasulyeyi 10 dakika haşlayıp suyunu dökün.","Soğan ve biberi zeytinyağında yumuşayana kadar kavurun.","Salçaları ve rendelenmiş domatesi ekleyip 3 dakika pişirin.","Fasulye ve sıcak suyu ilave edip kapağı aralık kısık ateşte 60-70 dakika pişirin.","Fasulyeler yumuşayınca tuz ve pul biberle tatlandırıp 10 dakika demlendirin."]},{"id":"ana-37","category":"ana","title":"Zeytinyağlı Taze Fasulye","fit":true,"desc":"Domatesle kendi suyunda pişen, soğuk da sıcak da yenebilen hafif klasik.","time":50,"servings":4,"difficulty":"Kolay","kcal":152,"protein":4,"carbs":16,"fat":8,"tags":["Vejetaryen","Zeytinyağlı","Düşük Kalori"],"ingredients":["600 g taze çalı fasulye","1 adet büyük kuru soğan","2 adet olgun domates","3 yemek kaşığı zeytinyağı","1 tatlı kaşığı toz şeker","150 ml sıcak su","Tuz"],"steps":["Fasulyelerin uçlarını ve kılçıklarını ayıklayıp ikiye bölün.","Soğanı yarım ay doğrayıp zeytinyağında 3 dakika çevirin.","Fasulyeleri ekleyip kapağı kapalı 10 dakika kendi buharında pişirin.","Rendelenmiş domates, şeker, tuz ve sıcak suyu ekleyin.","Kısık ateşte 30 dakika pişirin ve ılıyınca servis edin."]},{"id":"ana-38","category":"ana","title":"İmam Bayıldı","fit":false,"desc":"Yumuşacık patlıcanların bol soğanlı, sarımsaklı iç harçla doldurulduğu şahane bir zeytinyağlı.","time":70,"servings":4,"difficulty":"Orta","kcal":239,"protein":4,"carbs":22,"fat":15,"tags":["Vejetaryen","Zeytinyağlı","Geleneksel"],"ingredients":["4 adet orta boy patlıcan","2 adet büyük kuru soğan","6 diş sarımsak","3 adet domates","2 adet sivri biber","4 yemek kaşığı zeytinyağı","1 demet maydanoz","1 çay kaşığı toz şeker","200 ml sıcak su","Tuz"],"steps":["Patlıcanları alacalı soyup tuzlu suda 15 dakika bekletin ve kurulayın.","Patlıcanlara hafif zeytinyağı sürüp 200°C fırında 20 dakika yumuşatın.","Soğan, sarımsak ve biberi zeytinyağında kavurun; domates, şeker ve tuzu ekleyip 5 dakika pişirin, maydanozu katın.","Patlıcanları ortadan yarıp harcı içlerine doldurun.","Tepsiye sıcak suyu ekleyip 180°C fırında 30 dakika pişirin; ılık servis edin."]},{"id":"ana-39","category":"ana","title":"Sebzeli Fırın Frittata","fit":false,"desc":"Ispanak, biber ve beyaz peynirle fırında kabaran, akşam yemeğine yakışan yumurta keki.","time":30,"servings":3,"difficulty":"Kolay","kcal":255,"protein":22,"carbs":8,"fat":15,"tags":["Vejetaryen","Yüksek Protein","Düşük Karbonhidrat"],"ingredients":["6 adet yumurta","100 g ıspanak","1 adet kırmızı biber","1 adet küçük kabak","4 adet taze soğan","60 g az yağlı beyaz peynir","1 yemek kaşığı zeytinyağı","50 ml süt","Tuz, karabiber, kekik"],"steps":["Fırını 180°C'ye ısıtın; sebzeleri küçük doğrayın.","Fırına girebilen tavada zeytinyağıyla sebzeleri 5 dakika soteleyin.","Yumurta, süt, tuz, karabiber ve kekiği çırpın.","Karışımı sebzelerin üzerine dökün, ufalanmış peyniri serpin.","Ocakta 3 dakika tuttuktan sonra fırında 15 dakika, ortası sertleşene kadar pişirin."]},{"id":"ana-40","category":"ana","title":"Fırın Falafel Kasesi","fit":false,"desc":"Kızartmadan fırınlanan çıtır falafeller, bulgur, sebzeler ve tahinli sosla dolu bir kase.","time":50,"servings":3,"difficulty":"Orta","kcal":548,"protein":20,"carbs":72,"fat":20,"tags":["Vejetaryen","Vegan","Baklagil"],"ingredients":["250 g ıslatılmış çiğ nohut","1 adet kuru soğan","3 diş sarımsak","1 demet maydanoz","1 tatlı kaşığı kimyon","150 g pişmiş bulgur","2 yemek kaşığı tahin","1 adet limon","1 adet salatalık ve 2 adet domates","1 yemek kaşığı zeytinyağı","Tuz, karabiber"],"steps":["Nohut, soğan, sarımsak, maydanoz, kimyon ve tuzu robotta iri kum kıvamına getirin.","Harçtan ceviz büyüklüğünde toplar yapıp yağlı kâğıda dizin, zeytinyağı sürün.","200°C fırında ara sıra çevirerek 25 dakika pişirin.","Tahini limon suyu ve biraz suyla akışkan kıvamda çırpın.","Kaselere bulgur, doğranmış sebze ve falafelleri koyup tahin sosu gezdirin."]},{"id":"ana-41","category":"ana","title":"Kabak Spagetti Domates Soslu","fit":true,"desc":"Makarna yerine şerit kabakla hazırlanan, fesleğen kokulu düşük karbonhidratlı tabak.","time":20,"servings":2,"difficulty":"Kolay","kcal":194,"protein":8,"carbs":18,"fat":10,"tags":["Vejetaryen","Düşük Karbonhidrat","Düşük Kalori"],"ingredients":["3 adet orta boy kabak","300 g rendelenmiş domates","2 diş sarımsak","1 yemek kaşığı zeytinyağı","15 g rendelenmiş parmesan","Birkaç yaprak taze fesleğen","1 çay kaşığı kekik","Tuz, karabiber, pul biber"],"steps":["Kabakları spiral doğrayıcı veya soyacakla ince şeritler halinde kesin.","Zeytinyağında sarımsağı kokusu çıkana kadar çevirin.","Domatesi, kekiği ve pul biberi ekleyip 10 dakika koyulaştırın.","Kabak şeritlerini ekleyip yalnızca 2 dakika çevirin, suyunu salmasın.","Tuz, karabiber, parmesan ve fesleğenle hemen servis edin."]},{"id":"ana-42","category":"ana","title":"Brokolili Tam Buğday Makarna","fit":false,"desc":"Tam buğday makarna, brokoli ve cevizli sarımsak sosla lif dolu, doyurucu bir tabak.","time":25,"servings":3,"difficulty":"Kolay","kcal":483,"protein":17,"carbs":70,"fat":15,"tags":["Vejetaryen","Lifli","Pratik"],"ingredients":["250 g tam buğday makarna","300 g brokoli","3 diş sarımsak","2 yemek kaşığı zeytinyağı","30 g ceviz içi","30 g rendelenmiş parmesan","Yarım limon kabuğu rendesi","Tuz, karabiber, pul biber"],"steps":["Makarnayı tuzlu suda paket süresine göre haşlayın; son 3 dakika brokolileri de ekleyin.","Süzmeden önce bir kupa haşlama suyu ayırın.","Zeytinyağında ince doğranmış sarımsak ve cevizi 1 dakika kavurun.","Makarna ve brokoliyi tavaya alın, biraz haşlama suyuyla karıştırın.","Parmesan, limon kabuğu, karabiber ve pul biberle servis edin."]},{"id":"ana-43","category":"ana","title":"Tavuklu Buddha Bowl","fit":true,"desc":"Izgara tavuk, esmer pirinç, fırın sebze ve yoğurt sosla dengeli, renkli bir kase.","time":40,"servings":2,"difficulty":"Orta","kcal":470,"protein":38,"carbs":48,"fat":14,"tags":["Tavuk","Yüksek Protein","Dengeli"],"ingredients":["250 g tavuk göğsü","120 g esmer pirinç (çiğ)","1 adet küçük tatlı patates","1 kase kırmızı lahana ve roka","1/2 adet avokado","1 adet havuç","100 g yoğurt","1 tatlı kaşığı zeytinyağı","1 çay kaşığı köri veya kimyon","Tuz, limon"],"steps":["Esmer pirinci iki buçuk katı suda 30 dakika pişirin.","Tatlı patatesi küp doğrayıp baharat ve zeytinyağıyla 200°C fırında 25 dakika pişirin.","Tavuğu tuz ve baharatla ovup ızgarada pişirin, dilimleyin.","Yoğurdu limon ve tuzla çırpıp sos yapın.","Kaselere pirinç, sebzeler, avokado ve tavuğu bölümler halinde dizip sosu ekleyin."]},{"id":"ana-44","category":"ana","title":"Tam Buğday Tavuk Dürüm","fit":true,"desc":"Baharatlı tavuk, közlenmiş biber ve yoğurtlu sosun tam buğday lavaşa sarıldığı pratik öğün.","time":25,"servings":2,"difficulty":"Kolay","kcal":403,"protein":36,"carbs":40,"fat":11,"tags":["Tavuk","Pratik","Yüksek Protein"],"ingredients":["250 g tavuk göğsü","2 adet tam buğday lavaş","1 adet közlenmiş kırmızı biber","1 adet domates","Bir avuç marul","80 g süzme yoğurt","1 diş sarımsak","1 tatlı kaşığı zeytinyağı","1 çay kaşığı kekik ve yarım çay kaşığı pul biber","Tuz"],"steps":["Tavuğu ince şerit kesip zeytinyağı, kekik, pul biber ve tuzla harmanlayın.","Kızgın tavada 7-8 dakika, suyunu çekene kadar pişirin.","Yoğurdu ezilmiş sarımsak ve tuzla karıştırın.","Lavaşlara sos sürüp marul, domates, biber ve tavuğu yerleştirin.","Sıkıca sarıp tavada her yüzünü 1 dakika kızartın ve ikiye kesin."]},{"id":"ana-45","category":"ana","title":"Ev Yapımı Kayseri Usulü Mantı","fit":false,"desc":"Minik bohçalar, sarımsaklı yoğurt ve tereyağlı pul biber sosla sabır isteyen bir ziyafet.","time":120,"servings":4,"difficulty":"Zor","kcal":550,"protein":26,"carbs":62,"fat":22,"tags":["Geleneksel","Hamur İşi","Kıymalı"],"ingredients":["300 g un","1 adet yumurta","120 ml su","250 g az yağlı dana kıyma","1 adet küçük rendelenmiş soğan","400 g yoğurt","2 diş sarımsak","25 g tereyağı","1 tatlı kaşığı pul biber","Kuru nane, tuz, karabiber"],"steps":["Un, yumurta, su ve tuzla sert bir hamur yoğurup 30 dakika dinlendirin.","Kıymayı soğan, tuz ve karabiberle yoğurun.","Hamuru ince açıp 2-3 cm karelere kesin, her birine nohut kadar iç koyup bohça şeklinde kapatın.","Mantıları tuzlu kaynar suda 12-15 dakika haşlayıp süzün.","Üzerine sarımsaklı yoğurt dökün, tereyağında pul biber ve naneyi kızdırıp gezdirin."]},{"id":"ana-46","category":"ana","title":"Tam Buğday Sebzeli Pizza","fit":false,"desc":"İncecik tam buğday tabanı, ev yapımı domates sosu ve bol sebzeyle suçluluk duymadan pizza keyfi.","time":45,"servings":2,"difficulty":"Orta","kcal":486,"protein":26,"carbs":64,"fat":14,"tags":["Hamur İşi","Lifli","Vejetaryen"],"ingredients":["150 g tam buğday unu","90 ml ılık su","1 çay kaşığı kuru maya","1 tatlı kaşığı zeytinyağı","120 g domates püresi","80 g az yağlı rendelenmiş mozzarella","1 adet yeşil biber","100 g mantar","8 adet siyah zeytin","Kekik, fesleğen, tuz"],"steps":["Un, maya, tuz, ılık su ve zeytinyağıyla hamur yoğurup 20 dakika mayalandırın.","Domates püresini kekik ve tuzla 5 dakika pişirerek sos hazırlayın.","Hamuru yağlı kâğıt üzerinde ince açın ve fırını 230°C'ye ısıtın.","Sosu sürüp mozzarella, dilimlenmiş mantar, biber ve zeytini dağıtın.","12-14 dakika kenarları kızarana kadar pişirip fesleğenle servis edin."]},{"id":"ana-47","category":"ana","title":"Mantarlı Risotto","fit":false,"desc":"Parmesanla kremamsı kıvama gelen, mantar aromalı ve ipeksi İtalyan usulü pilav.","time":40,"servings":3,"difficulty":"Orta","kcal":414,"protein":12,"carbs":60,"fat":14,"tags":["Vejetaryen","Pirinç"],"ingredients":["200 g risotto pirinci","250 g mantar","1 adet kuru soğan","2 diş sarımsak","900 ml sıcak sebze suyu","1 yemek kaşığı zeytinyağı","15 g tereyağı","30 g rendelenmiş parmesan","Birkaç dal taze kekik","Tuz, karabiber"],"steps":["Mantarları dilimleyip zeytinyağında suyunu çekene kadar soteleyin ve kenara alın.","Aynı tavada ince doğranmış soğan ve sarımsağı yumuşatın.","Pirinci ekleyip 2 dakika, taneler parlayana kadar çevirin.","Sıcak suyu kepçe kepçe, her seferinde çekmesini bekleyerek 18-20 dakika ekleyin.","Mantar, tereyağı, parmesan ve kekiği katıp tuz, karabiberle tatlandırın; 2 dakika dinlendirin."]},{"id":"ana-48","category":"ana","title":"Karidesli Pad Thai Usulü Erişte","fit":false,"desc":"Pirinç eriştesi, karides, yumurta ve fıstığın tatlı-ekşi sosla sarmalandığı Uzak Doğu esintisi.","time":30,"servings":2,"difficulty":"Orta","kcal":544,"protein":30,"carbs":70,"fat":16,"tags":["Deniz Ürünü","Uzak Doğu","Erişte"],"ingredients":["150 g yassı pirinç eriştesi","200 g ayıklanmış karides","2 adet yumurta","100 g fasulye filizi","3 adet taze soğan","20 g kavrulmuş yer fıstığı","2 yemek kaşığı soya sosu","1 yemek kaşığı demirhindi ezmesi veya limon suyu","1 tatlı kaşığı esmer şeker","1 yemek kaşığı ayçiçek yağı"],"steps":["Erişteyi ılık suda 15 dakika yumuşatıp süzün.","Soya sosu, demirhindi ve şekeri karıştırarak sos hazırlayın.","Geniş tavada yağı kızdırıp karidesleri 2 dakika pişirip kenara alın.","Yumurtaları tavaya kırıp karıştırarak pişirin, ardından erişte ve sosu ekleyin.","Karides, filiz ve taze soğanı ekleyip 2 dakika çevirin; ezilmiş fıstık ve limonla servis edin."]},{"id":"ana-49","category":"ana","title":"Fırın Ratatuy","fit":true,"desc":"Patlıcan, kabak ve domates dilimlerinin otlu sos üzerinde fırınlandığı Provence usulü sebze yemeği.","time":60,"servings":4,"difficulty":"Orta","kcal":168,"protein":4,"carbs":20,"fat":8,"tags":["Vejetaryen","Vegan","Düşük Kalori"],"ingredients":["1 adet patlıcan","2 adet kabak","3 adet domates","1 adet kırmızı biber","1 adet kuru soğan","3 diş sarımsak","200 g domates püresi","2 yemek kaşığı zeytinyağı","Kekik, biberiye, fesleğen","Tuz, karabiber"],"steps":["Fırını 180°C'ye ısıtın; soğan, biber ve sarımsağı ince doğrayın.","Bunları 1 yemek kaşığı zeytinyağında soteleyip domates püresiyle 5 dakika pişirin ve fırın kabına yayın.","Patlıcan, kabak ve domatesi ince yuvarlak dilimleyin.","Dilimleri sırayla sosun üzerine dizip kalan zeytinyağı, otlar, tuz ve karabiberle tatlandırın.","Üzerini yağlı kâğıtla kapatıp 40 dakika, ardından açık olarak 10 dakika pişirin."]},{"id":"ana-50","category":"ana","title":"Somonlu Kinoa Tabağı","fit":false,"desc":"Tavada çıtır derili somon, sebzeli kinoa ve limonlu yoğurtla omega-3 dolu akşam tabağı.","time":30,"servings":2,"difficulty":"Orta","kcal":468,"protein":36,"carbs":36,"fat":20,"tags":["Balık","Yüksek Protein","Omega-3"],"ingredients":["2 adet somon fileto (yaklaşık 280 g)","100 g kinoa","1 adet kabak","1 adet havuç","Bir avuç ıspanak","1 tatlı kaşığı zeytinyağı","80 g yoğurt","1 adet limon","Dereotu, tuz, karabiber"],"steps":["Kinoayı yıkayıp iki katı suda 15 dakika pişirin.","Kabak ve havucu küçük küp doğrayıp zeytinyağında 5 dakika soteleyin, ıspanak ve kinoayı ekleyin.","Somonu tuz ve karabiberle tatlandırıp yapışmaz tavada derili tarafından 4 dakika pişirin.","Çevirip 3 dakika daha pişirin.","Yoğurdu limon ve dereotuyla karıştırıp kinoa ve somonla birlikte servis edin."]},{"id":"ara-01","category":"ara","title":"Humus ve Sebze Çubukları","fit":true,"desc":"Kremamsı ev yapımı humus, çıtır havuç, salatalık ve biber çubuklarıyla doyurucu bir ara öğün.","time":15,"servings":4,"difficulty":"Kolay","kcal":190,"protein":7,"carbs":20,"fat":9,"tags":["vegan","lifli","pratik"],"ingredients":["400 g haşlanmış nohut","2 yemek kaşığı tahin","1 limonun suyu","1 diş sarımsak","1 yemek kaşığı zeytinyağı","50 ml soğuk su","2 adet havuç","1 adet salatalık","1 adet kırmızı biber","1 çay kaşığı kimyon"],"steps":["Nohut, tahin, limon suyu, sarımsak ve kimyonu robottan geçirin.","Soğuk suyu azar azar ekleyerek pürüzsüz kıvam elde edin.","Sebzeleri parmak kalınlığında çubuklar halinde kesin.","Humusu kaseye alıp üzerine zeytinyağı gezdirin ve sebzelerle servis edin."]},{"id":"ara-02","category":"ara","title":"Fırında Baharatlı Nohut Cipsi","fit":true,"desc":"Paprika ve kimyonla fırında çıtırlaşan, cips yerine keyifle yenebilecek nohut atıştırmalığı.","time":40,"servings":3,"difficulty":"Kolay","kcal":165,"protein":8,"carbs":22,"fat":5,"tags":["vegan","çıtır","fırın"],"ingredients":["300 g haşlanmış nohut","1 yemek kaşığı zeytinyağı","1 çay kaşığı toz kırmızı biber","1/2 çay kaşığı kimyon","1/2 çay kaşığı sarımsak tozu","1/2 çay kaşığı tuz"],"steps":["Fırını 200°C'ye ısıtın.","Nohutları süzüp havluyla iyice kurulayın.","Zeytinyağı ve baharatlarla harmanlayın.","Tepsiye tek kat yayıp ara ara karıştırarak 30-35 dakika çıtırlaşana kadar pişirin.","Soğuyunca servis edin."]},{"id":"ara-03","category":"ara","title":"Naneli Cacık","fit":true,"desc":"Serinletici, probiyotik açısından zengin ve hafif klasik yoğurtlu salatalık.","time":10,"servings":2,"difficulty":"Kolay","kcal":110,"protein":8,"carbs":10,"fat":4,"tags":["probiyotik","serinletici","vejetaryen"],"ingredients":["300 g süzme olmayan yoğurt","1 adet salatalık","1 diş sarımsak","1 çay kaşığı kuru nane","100 ml soğuk su","1 tatlı kaşığı zeytinyağı","Tuz"],"steps":["Salatalığı küçük küpler halinde doğrayın ya da rendeleyin.","Sarımsağı ezip yoğurt ve tuzla çırpın.","Suyu ekleyip kıvamı ayarlayın ve salatalığı katın.","Üzerine nane serpip zeytinyağı gezdirerek soğuk servis edin."]},{"id":"ara-04","category":"ara","title":"Yoğurtlu Meyve Kasesi","fit":true,"desc":"Süzme yoğurt, taze meyveler ve yulafla hazırlanan proteinli, tatlı krizini bastıran kase.","time":5,"servings":1,"difficulty":"Kolay","kcal":230,"protein":15,"carbs":30,"fat":5,"tags":["protein","tatlı","kahvaltılık"],"ingredients":["150 g süzme yoğurt","80 g çilek","1/2 adet muz","20 g yulaf ezmesi","1 tatlı kaşığı bal","5 g chia tohumu"],"steps":["Yoğurdu kaseye alın.","Çilekleri ve muzu dilimleyin.","Meyveleri yoğurdun üzerine yerleştirin.","Yulaf ve chia serpip balı gezdirin."]},{"id":"ara-05","category":"ara","title":"Fıstık Ezmeli Elma Dilimleri","fit":false,"desc":"Ekşi elmanın fıstık ezmesi ve tarçınla buluştuğu enerjik, çocukların da seveceği atıştırmalık.","time":5,"servings":1,"difficulty":"Kolay","kcal":245,"protein":6,"carbs":28,"fat":13,"tags":["enerji","pratik","tatlı"],"ingredients":["1 adet orta boy yeşil elma","25 g yer fıstığı ezmesi","1 tatlı kaşığı kavrulmuş yulaf","1 tutam tarçın"],"steps":["Elmanın çekirdek evini çıkarıp halka veya dilim şeklinde kesin.","Dilimlerin üzerine fıstık ezmesini ince sürün.","Yulaf ve tarçın serperek hemen servis edin."]},{"id":"ara-06","category":"ara","title":"Ton Balıklı Salatalık Kanepe","fit":true,"desc":"Ekmek yerine salatalık dilimleri üzerinde yoğurtlu ton balığı; düşük karbonhidratlı ve proteinli.","time":10,"servings":2,"difficulty":"Kolay","kcal":125,"protein":16,"carbs":5,"fat":4,"tags":["protein","düşük karbonhidrat","balık"],"ingredients":["120 g süzülmüş suyunda ton balığı","2 yemek kaşığı süzme yoğurt","1 adet büyük salatalık","1/2 limonun suyu","1 yemek kaşığı doğranmış dereotu","1 tatlı kaşığı zeytinyağı","Karabiber"],"steps":["Ton balığını çatalla ezip yoğurt, limon suyu, dereotu ve karabiberle karıştırın.","Salatalığı 1 cm kalınlığında yuvarlak dilimleyin.","Her dilimin üzerine bir kaşık harç koyun.","Zeytinyağı damlatıp servis edin."]},{"id":"ara-07","category":"ara","title":"Haşlanmış Yumurta ve Avokado","fit":true,"desc":"Kaliteli yağ ve protein dengesiyle uzun süre tok tutan hızlı bir ara öğün.","time":12,"servings":1,"difficulty":"Kolay","kcal":240,"protein":13,"carbs":7,"fat":18,"tags":["keto","protein","sağlıklı yağ"],"ingredients":["2 adet yumurta","1/2 adet avokado","1 tutam pul biber","1 tutam deniz tuzu","Birkaç damla limon suyu"],"steps":["Yumurtaları kaynar suda 9 dakika haşlayıp soğuk suya alın.","Avokadoyu dilimleyip limon suyu damlatın.","Yumurtaları soyup ikiye kesin.","Tabağa dizip tuz ve pul biber serperek servis edin."]},{"id":"ara-08","category":"ara","title":"Fırında Kabak Mücver","fit":true,"desc":"Kızartma yerine fırında pişen, dereotu ve beyaz peynir kokulu hafif mücver.","time":40,"servings":4,"difficulty":"Orta","kcal":150,"protein":9,"carbs":12,"fat":7,"tags":["fırın","vejetaryen","sebze"],"ingredients":["3 adet orta boy kabak","2 adet yumurta","60 g beyaz peynir","4 yemek kaşığı tam buğday unu","1 adet taze soğan","1/2 demet dereotu","1 yemek kaşığı zeytinyağı","Tuz, karabiber"],"steps":["Kabakları rendeleyip tuzlayın, 10 dakika bekletip suyunu iyice sıkın.","Yumurta, ufalanmış peynir, un, doğranmış soğan ve dereotunu ekleyip karıştırın.","Fırını 200°C'ye ısıtın, yağlı kağıt serili tepsiye kaşıkla küçük yuvarlaklar bırakın.","Üzerlerine fırçayla zeytinyağı sürüp 25 dakika, yarısında çevirerek pişirin."]},{"id":"ara-09","category":"ara","title":"Tam Buğday Lavaş Cipsi ve Acılı Ezme","fit":false,"desc":"Fırında çıtırlaşan lavaş üçgenleri, domates ve biberle hazırlanan ev yapımı ezmeyle.","time":25,"servings":3,"difficulty":"Kolay","kcal":205,"protein":6,"carbs":30,"fat":7,"tags":["çıtır","vegan","paylaşımlık"],"ingredients":["2 adet tam buğday lavaş","1 yemek kaşığı zeytinyağı","2 adet domates","1 adet sivri biber","1/2 adet kuru soğan","1/2 demet maydanoz","1 tatlı kaşığı nar ekşisi","1 tatlı kaşığı biber salçası","1/2 çay kaşığı pul biber"],"steps":["Lavaşları üçgen kesip zeytinyağı sürün ve 180°C fırında 8-10 dakika kızartın.","Domates, biber, soğan ve maydanozu çok ince kıyın.","Salça, nar ekşisi ve pul biberle yoğurun, fazla suyunu süzün.","Çıtır lavaşları ezmeyle birlikte servis edin."]},{"id":"ara-10","category":"ara","title":"Muzlu Protein Smoothie","fit":true,"desc":"Yoğurt, süt ve yulafla hazırlanan, antrenman sonrası için ideal kremamsı içecek.","time":5,"servings":1,"difficulty":"Kolay","kcal":290,"protein":20,"carbs":40,"fat":6,"tags":["protein","antrenman sonrası","içecek"],"ingredients":["1 adet dondurulmuş muz","200 ml yağsız süt","100 g süzme yoğurt","20 g yulaf ezmesi","1 tatlı kaşığı kakao","1 tutam tarçın"],"steps":["Muzu dilimleyip dondurucuda en az 2 saat bekletin.","Tüm malzemeleri blendera koyun.","Pürüzsüz olana kadar 1 dakika çekin ve hemen için."]},{"id":"ara-11","category":"ara","title":"Limonlu Haşlanmış Edamame","fit":true,"desc":"Deniz tuzu ve limonla tatlandırılmış, bitkisel protein deposu yeşil soya fasulyesi.","time":10,"servings":2,"difficulty":"Kolay","kcal":165,"protein":14,"carbs":11,"fat":7,"tags":["vegan","bitkisel protein","pratik"],"ingredients":["300 g kabuklu dondurulmuş edamame","1 litre su","1 çay kaşığı iri deniz tuzu","1/2 limonun kabuk rendesi","1/2 çay kaşığı pul biber"],"steps":["Suyu tuzlayıp kaynatın.","Edamameleri ekleyip 5 dakika haşlayın ve süzün.","Sıcakken deniz tuzu, limon kabuğu ve pul biberle harmanlayın.","Kabuklarından sıyırarak yiyin."]},{"id":"ara-12","category":"ara","title":"Fırında Tatlı Patates Çubukları","fit":true,"desc":"Dışı çıtır içi yumuşak, tarçın ve paprikayla fırınlanan hafif patates alternatifi.","time":35,"servings":2,"difficulty":"Kolay","kcal":200,"protein":3,"carbs":34,"fat":6,"tags":["fırın","glütensiz","vegan"],"ingredients":["2 adet orta boy tatlı patates","1 yemek kaşığı zeytinyağı","1 tatlı kaşığı mısır nişastası","1/2 çay kaşığı tatlı toz biber","1 tutam tarçın","Tuz"],"steps":["Fırını 220°C'ye ısıtın.","Tatlı patatesleri kabuklu şekilde parmak kalınlığında kesip kurulayın.","Nişasta, zeytinyağı ve baharatlarla harmanlayın.","Tepsiye aralıklı dizip yarısında çevirerek 25 dakika pişirin."]},{"id":"ara-13","category":"ara","title":"Peynirli Mantar Dolması","fit":true,"desc":"Lor ve kaşar karışımıyla doldurulup fırınlanan, sucuk tadında baharatlı mantar kapakları.","time":25,"servings":2,"difficulty":"Orta","kcal":160,"protein":13,"carbs":6,"fat":9,"tags":["düşük karbonhidrat","fırın","vejetaryen"],"ingredients":["12 adet iri kültür mantarı","80 g lor peyniri","30 g rendelenmiş kaşar","1 diş sarımsak","1 yemek kaşığı kıyılmış maydanoz","1 tatlı kaşığı zeytinyağı","1/2 çay kaşığı kekik","Karabiber"],"steps":["Mantarların saplarını çıkarıp ince kıyın, kapakları silin.","Sapları sarımsakla zeytinyağında 2 dakika soteleyin.","Lor, maydanoz, kekik ve karabiberle karıştırıp kapaklara doldurun.","Üzerine kaşar serpip 200°C fırında 15 dakika pişirin."]},{"id":"ara-14","category":"ara","title":"Limonlu Guacamole ve Sebze","fit":true,"desc":"Olgun avokado, domates ve kişnişle hazırlanan, sebze çubuklarına eşlik eden lezzetli sos.","time":10,"servings":3,"difficulty":"Kolay","kcal":170,"protein":3,"carbs":12,"fat":13,"tags":["vegan","sağlıklı yağ","glütensiz"],"ingredients":["2 adet olgun avokado","1 adet küçük domates","1/4 adet mor soğan","1 misket limonunun suyu","2 yemek kaşığı kıyılmış kişniş","1 adet yeşil biber","1 adet havuç","Tuz"],"steps":["Avokadoları çatalla hafif iri kalacak şekilde ezin.","Çekirdeği alınmış domatesi ve soğanı küçük doğrayıp ekleyin.","Limon suyu, kişniş ve tuzla karıştırın.","Biber ve havucu çubuk halinde kesip guacamoleyle servis edin."]},{"id":"ara-15","category":"ara","title":"Lor Peynirli Çıtır Rulo","fit":false,"desc":"Yufka arasında dereotlu lor dolgusuyla fırında çıtırlaşan, çay saatine uygun atıştırmalık.","time":30,"servings":4,"difficulty":"Orta","kcal":230,"protein":12,"carbs":24,"fat":9,"tags":["fırın","çay saati","vejetaryen"],"ingredients":["2 adet yufka","200 g lor peyniri","1 adet yumurta","100 ml süt","1 yemek kaşığı zeytinyağı","1/2 demet dereotu","1 tatlı kaşığı çörek otu"],"steps":["Lor, doğranmış dereotu ve yumurta beyazını karıştırın.","Yufkaları 8 üçgene kesip süt ve zeytinyağı karışımıyla hafifçe nemlendirin.","Geniş kenara iç harcı koyup sıkıca sarın.","Üzerlerine yumurta sarısı sürüp çörek otu serpin ve 190°C fırında 20 dakika pişirin."]},{"id":"ara-16","category":"ara","title":"Kuru Meyve ve Kuruyemiş Karışımı","fit":false,"desc":"Çiğ badem, ceviz, kuru kayısı ve üzümle hazırlanan, çantada taşınabilir enerji paketi.","time":5,"servings":4,"difficulty":"Kolay","kcal":270,"protein":7,"carbs":24,"fat":17,"tags":["enerji","taşınabilir","vegan"],"ingredients":["40 g çiğ badem","30 g ceviz içi","30 g çiğ fındık","50 g kuru kayısı","30 g kuru üzüm","20 g kabak çekirdeği"],"steps":["Kayısıları küçük parçalara kesin.","Tüm malzemeleri geniş bir kapta karıştırın.","Karışımı dört eşit porsiyona bölüp ağzı kapalı kaplarda saklayın."]},{"id":"ara-17","category":"ara","title":"Yağsız Baharatlı Patlamış Mısır","fit":true,"desc":"Yağ kullanmadan patlatılıp baharatlanan, hacimli ve düşük kalorili film gecesi atıştırmalığı.","time":10,"servings":2,"difficulty":"Kolay","kcal":120,"protein":4,"carbs":24,"fat":1,"tags":["düşük kalori","lifli","vegan"],"ingredients":["60 g patlatmalık mısır","1/2 çay kaşığı toz kırmızı biber","1/2 çay kaşığı kekik","1/4 çay kaşığı sarımsak tozu","1/2 çay kaşığı tuz","1 tatlı kaşığı su"],"steps":["Mısırları kalın tabanlı, kapaklı bir tencereye koyup orta ateşe alın.","Tencereyi ara ara sallayarak patlamalar yavaşlayana kadar pişirin.","Mısırları kaba alıp birkaç damla su püskürtün.","Baharatları ve tuzu serpip kabı sallayarak harmanlayın."]},{"id":"ara-18","category":"ara","title":"Salatalıklı Ferah Yeşil Smoothie","fit":true,"desc":"Ispanak, elma, salatalık ve zencefille ferahlatan, vitamin dolu hafif içecek.","time":5,"servings":1,"difficulty":"Kolay","kcal":150,"protein":5,"carbs":28,"fat":3,"tags":["detoks","vitamin","içecek"],"ingredients":["1 avuç taze ıspanak","1 adet yeşil elma","1/2 adet salatalık","1/2 adet muz","1 dilim taze zencefil","1/2 limonun suyu","150 ml soğuk su","5 g keten tohumu"],"steps":["Ispanağı yıkayıp elmanın çekirdeklerini çıkarın.","Tüm malzemeleri doğrayıp blendera koyun.","Pürüzsüz olana kadar çekin ve soğuk servis edin."]},{"id":"ara-19","category":"ara","title":"Fırında Light Sigara Böreği","fit":false,"desc":"Kızartma yerine fırında pişen, az yağlı beyaz peynirli klasik sigara böreği.","time":35,"servings":4,"difficulty":"Orta","kcal":220,"protein":11,"carbs":26,"fat":8,"tags":["fırın","klasik","vejetaryen"],"ingredients":["3 adet yufka","150 g az yağlı beyaz peynir","1/2 demet maydanoz","1 adet yumurta","80 ml süt","1 yemek kaşığı zeytinyağı","1 tatlı kaşığı susam"],"steps":["Peyniri ufalayıp kıyılmış maydanozla karıştırın.","Yufkaları 8 üçgene bölün.","Üçgenlerin geniş kenarına harç koyup kenarları içe katlayarak sıkıca sarın.","Yumurta, süt ve zeytinyağını çırpıp böreklerin üzerine sürün, susam serpin.","200°C fırında 20 dakika kızarana kadar pişirin."]},{"id":"ara-20","category":"ara","title":"Cevizli Yoğurtlu Pancar","fit":true,"desc":"Fırınlanmış pancarın sarımsaklı yoğurt ve cevizle buluştuğu renkli, lifli meze.","time":60,"servings":4,"difficulty":"Kolay","kcal":140,"protein":6,"carbs":13,"fat":7,"tags":["meze","lifli","vejetaryen"],"ingredients":["3 adet orta boy pancar","250 g süzme yoğurt","1 diş sarımsak","25 g ceviz içi","1 tatlı kaşığı zeytinyağı","1 tatlı kaşığı nar ekşisi","Tuz"],"steps":["Pancarları folyoya sarıp 200°C fırında 50 dakika pişirin.","Soğuyunca kabuklarını soyup rendeleyin.","Yoğurdu ezilmiş sarımsak ve tuzla çırpın, pancarı ekleyin.","Tabağa alıp üzerine kırılmış ceviz, zeytinyağı ve nar ekşisi gezdirin."]},{"id":"tat-01","category":"tatli","title":"Kakaolu Hurmalı Toplar","fit":true,"desc":"Hurma, ceviz ve kakaoyla hazırlanan, rafine şeker içermeyen pişirmesiz lokmalık tatlı toplar.","time":15,"servings":4,"difficulty":"Kolay","kcal":200,"protein":4,"carbs":26,"fat":9,"tags":["şekersiz","pişirmesiz","vegan"],"ingredients":["120 g çekirdeksiz hurma","50 g ceviz içi","20 g yulaf ezmesi","1 yemek kaşığı kakao","1 tutam tuz","1 yemek kaşığı hindistan cevizi rendesi"],"steps":["Hurmalar çok kuruysa 10 dakika ılık suda bekletip süzün.","Ceviz ve yulafı mutfak robotunda iri kum kıvamında çekin.","Hurma, kakao ve tuzu ekleyip macun olana dek çekin.","Cevizden biraz büyük toplar yapıp hindistan cevizine bulayın, buzdolabında sertleştirin."]},{"id":"tat-02","category":"tatli","title":"Fırında Tarçınlı Elma","fit":true,"desc":"Cevizli ve tarçınlı iç harçla fırında yumuşayan, kendi suyunda karamelleşen elmalar.","time":35,"servings":2,"difficulty":"Kolay","kcal":185,"protein":3,"carbs":32,"fat":5,"tags":["fırın","lifli","vejetaryen"],"ingredients":["2 adet orta boy elma","15 g ceviz içi","1 tatlı kaşığı bal","1 çay kaşığı tarçın","2 yemek kaşığı su","1 tutam karanfil"],"steps":["Fırını 180°C'ye ısıtın, elmaların çekirdek kısmını oyun.","Kırılmış ceviz, bal ve tarçını karıştırıp elmaların içine doldurun.","Elmaları küçük bir fırın kabına dizip dibine su ve karanfil ekleyin.","25-30 dakika, elmalar yumuşayana dek pişirin.","İsterseniz bir kaşık yoğurtla ılık servis edin."]},{"id":"tat-03","category":"tatli","title":"Muzlu Yoğurt Dondurması","fit":true,"desc":"Donmuş muz ve süzme yoğurdun blenderda krema kıvamına geldiği şekersiz ev dondurması.","time":10,"servings":2,"difficulty":"Kolay","kcal":175,"protein":9,"carbs":28,"fat":3,"tags":["şekersiz","dondurma","pişirmesiz"],"ingredients":["2 adet olgun muz (dilimlenip dondurulmuş)","150 g süzme yoğurt","1/2 çay kaşığı vanilya özü","1 tutam tarçın","10 g bitter çikolata parçası"],"steps":["Muzları en az 4 saat önceden dilimleyip dondurun.","Donmuş muz, yoğurt ve vanilyayı blenderda krema kıvamına gelene dek çekin.","Tarçın ekleyip kaselere paylaştırın.","Hemen yumuşak servis edin veya 1 saat dondurucuda bekletip top yapın; üzerine çikolata serpin."]},{"id":"tat-04","category":"tatli","title":"Yulaflı Muzlu Kurabiye","fit":true,"desc":"Sadece muz, yulaf ve kuru üzümle yapılan, un ve şeker eklenmemiş yumuşak kurabiyeler.","time":25,"servings":4,"difficulty":"Kolay","kcal":180,"protein":4,"carbs":30,"fat":5,"tags":["şekersiz","fırın","vegan"],"ingredients":["2 adet olgun muz","120 g yulaf ezmesi","25 g kuru üzüm","15 g fındık içi","1 çay kaşığı tarçın","1 tutam tuz"],"steps":["Fırını 180°C'ye ısıtıp tepsiye pişirme kağıdı serin.","Muzları çatalla iyice ezin.","Yulaf, kuru üzüm, kırılmış fındık, tarçın ve tuzu ekleyip karıştırın.","Kaşıkla 12 parça halinde tepsiye alıp hafifçe bastırın.","15-18 dakika kenarları kızarana dek pişirin; kişi başı 3 adet."]},{"id":"tat-05","category":"tatli","title":"Kakaolu Muzlu Chia Puding","fit":true,"desc":"Kakao ve muzla tatlanan, gece bekletilerek yoğun kıvam kazanan çikolatalı chia pudingi.","time":10,"servings":2,"difficulty":"Kolay","kcal":215,"protein":8,"carbs":26,"fat":9,"tags":["hazırla-sakla","lifli","şekersiz"],"ingredients":["40 g chia tohumu","300 ml yarım yağlı süt","1 adet olgun muz","1 yemek kaşığı kakao","1/2 çay kaşığı vanilya özü","Birkaç ahududu"],"steps":["Muzu süt, kakao ve vanilyayla blenderda pürüzsüz çekin.","Karışımı chia tohumlarıyla bir kapta birleştirin.","10 dakika sonra tekrar karıştırıp buzdolabında en az 4 saat bekletin.","Kaselere paylaştırıp ahududuyla servis edin."]},{"id":"tat-06","category":"tatli","title":"Protein Brownie","fit":true,"desc":"Yulaf unu, yumurta ve yoğurtla yapılan, nemli dokulu ve kakaosu bol hafif brownie.","time":35,"servings":8,"difficulty":"Orta","kcal":165,"protein":7,"carbs":18,"fat":7,"tags":["yüksek protein","fırın","düşük şeker"],"ingredients":["80 g yulaf unu","30 g kakao","2 adet yumurta","150 g süzme yoğurt","2 adet olgun muz","40 g fıstık ezmesi (şekersiz)","30 g bitter çikolata parçası","1 çay kaşığı kabartma tozu"],"steps":["Fırını 175°C'ye ısıtın, 20x20 cm kalıbı kağıtla kaplayın.","Muzları ezip yumurta, yoğurt ve fıstık ezmesiyle çırpın.","Yulaf unu, kakao ve kabartma tozunu ekleyip karıştırın.","Çikolata parçalarını katıp hamuru kalıba yayın.","20-22 dakika pişirin, tamamen soğuyunca 8 dilime kesin."]},{"id":"tat-07","category":"tatli","title":"Hafif Fırın Sütlaç","fit":true,"desc":"Yarım yağlı süt ve azaltılmış şekerle hazırlanan, üzeri fırında hafif kızartılmış sütlaç.","time":50,"servings":4,"difficulty":"Orta","kcal":210,"protein":7,"carbs":36,"fat":4,"tags":["geleneksel","düşük şeker","fırın"],"ingredients":["60 g pirinç","250 ml su","800 ml yarım yağlı süt","40 g toz şeker","15 g pirinç unu","1/2 çay kaşığı vanilya özü","1 tutam tarçın"],"steps":["Pirinci suyla, su çekilip taneler yumuşayana dek 15 dakika haşlayın.","Sütü ekleyip ara ara karıştırarak 15 dakika pişirin.","Pirinç ununu biraz soğuk sütle açıp şekerle birlikte tencereye ekleyin, 5 dakika koyulaşana dek karıştırın.","Vanilyayı ekleyip toprak kaselere paylaştırın.","Kaseleri su dolu tepsiye dizip fırının üst ızgarasında üzeri kızarana dek tutun, soğutup tarçınla servis edin."]},{"id":"tat-08","category":"tatli","title":"Çilekli Yoğurt Tart","fit":true,"desc":"Yulaf-ceviz tabanlı, süzme yoğurt dolgulu ve taze çileklerle kaplı hafif bir soğuk tart.","time":30,"servings":8,"difficulty":"Orta","kcal":170,"protein":7,"carbs":20,"fat":7,"tags":["soğuk tatlı","meyveli","düşük şeker"],"ingredients":["120 g yulaf ezmesi","50 g ceviz içi","60 g çekirdeksiz hurma","400 g süzme yoğurt","1 yemek kaşığı bal","1/2 limonun kabuk rendesi","250 g çilek","1 yemek kaşığı eritilmiş hindistan cevizi yağı"],"steps":["Fırını 180°C'ye ısıtın; yulaf, ceviz, hurma ve hindistan cevizi yağını robotta yapışkan kıvama gelene dek çekin.","Karışımı 22 cm tart kalıbının tabanına ve kenarlarına bastırıp 10 dakika pişirin, soğutun.","Yoğurdu bal ve limon kabuğuyla çırpın.","Soğuyan tabana yoğurt kremasını yayın.","Dilimlenmiş çilekleri dizip buzdolabında en az 2 saat bekletin, 8 dilime kesin."]},{"id":"tat-09","category":"tatli","title":"Hafif Kabak Tatlısı","fit":true,"desc":"Balkabağının az şekerle kendi suyunda piştiği, cevizli ve yoğurtlu dengeli bir kış tatlısı.","time":50,"servings":4,"difficulty":"Kolay","kcal":195,"protein":5,"carbs":30,"fat":6,"tags":["geleneksel","düşük şeker","mevsimlik"],"ingredients":["800 g balkabağı","40 g toz şeker","50 ml su","1 adet tarçın çubuğu","4 adet karanfil","30 g ceviz içi","100 g süzme yoğurt"],"steps":["Kabağı soyup 3-4 cm'lik parçalar halinde kesin.","Tencereye dizip şekeri serpin ve 30 dakika suyunu salması için bekletin.","Su, tarçın ve karanfili ekleyip kapağı kapalı kısık ateşte 25-30 dakika pişirin.","Soğuyan kabakları tabaklara alın.","Birer kaşık süzme yoğurt ve kırılmış cevizle servis edin."]},{"id":"tat-10","category":"tatli","title":"Fıstık Ezmeli Enerji Barı","fit":true,"desc":"Yulaf, fıstık ezmesi ve kuru meyvelerle hazırlanan, buzdolabında sertleşen pişirmesiz bar.","time":15,"servings":8,"difficulty":"Kolay","kcal":225,"protein":7,"carbs":24,"fat":11,"tags":["pişirmesiz","enerji","vejetaryen"],"ingredients":["150 g yulaf ezmesi","100 g şekersiz fıstık ezmesi","80 g çekirdeksiz hurma","30 g bal","30 g kuru kayısı","20 g kabak çekirdeği içi","1 tutam tuz"],"steps":["Hurmayı robotta macun kıvamına gelene dek çekin.","Fıstık ezmesi ve balı hafifçe ısıtıp hurmayla karıştırın.","Yulaf, doğranmış kayısı, kabak çekirdeği ve tuzu ekleyip iyice yoğurun.","Karışımı kağıt serili 20x20 cm kaba sıkıca bastırın.","Buzdolabında 2 saat bekletip 8 bar halinde kesin."]}];
